  // 統一綁定所有範本按鈕
  document.querySelectorAll('._admin-gm-tmpl-btn').forEach(function(btn){
    btn.onclick = function(){
      const _key = btn.dataset.tmpl;
      const _tmpl = _GM_TEMPLATES[_key];
      if(!_tmpl){ console.warn('[GM 範本] 找不到 key=' + _key); return; }
      const _textEl = document.getElementById('_admin-gm-text');
      const _typeEl = document.getElementById('_admin-gm-type');
      const _colorEl = document.getElementById('_admin-gm-color');
      if(!_textEl) return;
      if(_textEl.value.trim() && !confirm('公告內容欄目前有文字,要覆蓋成此範本嗎?')) return;
      _textEl.value = _tmpl.text;
      if(_typeEl && _tmpl.type) _typeEl.value = _tmpl.type;
      if(_colorEl && _tmpl.color) _colorEl.value = _tmpl.color;
      const _res = document.getElementById('_admin-gm-result');
      if(_res){
        _res.style.color = '#aaccff';
        _res.textContent = '✅ 已填入範本「' + btn.textContent.trim() + '」— 確認後可微調內容,然後按「📢 發送給所有玩家」';
      }
      _textEl.focus();
    };
  });

  // 回填總玩家數
  document.getElementById('_admin-backfill-players').onclick = async () => {
    const btn = document.getElementById('_admin-backfill-players');
    const res = document.getElementById('_admin-backfill-result');
    if(!window._fbBackfillTotalPlayers){
      res.style.color = '#ff6666';
      res.textContent = '❌ Firebase 尚未就緒，請稍後再試';
      return;
    }
    btn.disabled = true;
    btn.textContent = '掃描中...';
    res.style.color = '#88ccff';
    res.textContent = '正在掃描 /players 集合...';
    try {
      const count = await window._fbBackfillTotalPlayers();
      res.style.color = '#88ff88';
      res.textContent = `✅ 完成！共找到 ${count} 位歷史玩家，已寫入 totalPlayers。`;
    } catch(e){
      res.style.color = '#ff6666';
      res.textContent = '❌ 失敗：' + (e && e.code || e.message || '未知錯誤');
    } finally {
      btn.disabled = false;
      btn.textContent = '▶ 執行回填';
    }
  };

  // 設定冒險次數
  document.getElementById('_admin-set-adventures').onclick = async () => {
    const input = document.getElementById('_admin-adv-input');
    const btn = document.getElementById('_admin-set-adventures');
    const res = document.getElementById('_admin-adv-result');
    const val = parseInt(input.value, 10);
    if(isNaN(val) || val < 0){
      res.style.color = '#ff6666';
      res.textContent = '❌ 請輸入 0 或以上的整數';
      return;
    }
    if(!window._fbSetAdventureTotal){
      res.style.color = '#ff6666';
      res.textContent = '❌ Firebase 尚未就緒，請稍後再試';
      return;
    }
    if(!confirm(`確定要把「累計冒險次數」設定為 ${val} 嗎？這會覆寫現有值。`)) return;
    btn.disabled = true;
    btn.textContent = '設定中...';
    try {
      await window._fbSetAdventureTotal(val);
      res.style.color = '#ff99cc';
      res.textContent = `✅ 已設定 totalAdventures = ${val}`;
    } catch(e){
      res.style.color = '#ff6666';
      res.textContent = '❌ 失敗：' + (e && e.code || e.message || '未知錯誤');
    } finally {
      btn.disabled = false;
      btn.textContent = '▶ 設定';
    }
  };

  // ════════════════════════════════════════════════════════════════
  // ★ v3.13.15(2026-06-02) — 鬥技場預設陣容管理(系統 5 套保底敵手)
  // ────────────────────────────────────────────────────────────────
  // Firestore 結構:arenaSystemTeams/main {teams: [{id,name,heroes:[4],elements:[4],desc?}×5], updatedAt, updatedBy}
  // 流程:GM 點「載入」→ 從雲端讀 + 渲染 → 編輯每套(隊名/英雄/元素)→ 點「儲存」→ 寫回 Firestore
  // 即時生效:儲存後玩家下次抽取(arena.js _arenaFetchTeamPool 觸發時)就會套用
  // ════════════════════════════════════════════════════════════════

  // 內建 5 套陣容(後備,當雲端沒資料時用,跟 arena.js 內 ARENA_AI_TEAMS_DEFAULT 對齊)
  // ★ v3.13.27(2026-06-03)— 老師指定組合更新(跟 arena.js 同步)
  const _ARENA_PRESET_DEFAULT = [
    { id:'sys_1', name:'[鬥技場預設] 神殿守護隊', heroes:['聖騎士','占星師','天神宙斯','祭司'],   elements:['light','dark','wind','grass'] },
    { id:'sys_2', name:'[鬥技場預設] 雷霆控場隊', heroes:['雷法師','守衛','玉藻前','救醫馬'],   elements:['wind','light','fire','grass'] },
    { id:'sys_3', name:'[鬥技場預設] 舞動陣勢隊', heroes:['舞者','直笛團員','吟遊詩人','弦樂團員'], elements:['earth','wind','grass','light'] },
    { id:'sys_4', name:'[鬥技場預設] 快攻刺客隊', heroes:['刺客','田徑隊員','武器精靈','神槍手'],   elements:['dark','wind','light','fire'] },
    { id:'sys_5', name:'[鬥技場預設] 元素法團隊', heroes:['火法師','冰法師','雷法師','菇女'],   elements:['fire','water','wind','grass'] },
  ];
  // 工作狀態:當前編輯中的 5 套陣容
  let _arenaPresetWorking = JSON.parse(JSON.stringify(_ARENA_PRESET_DEFAULT));

  // 取得可選英雄名單(從 HERO_DB 排除 BOSS / 日本菁英小怪 / 活動限定)
  // ★ v3.13.27(2026-06-03) — 根因修補(老師反映「所有 BOSS 和菁英都在裡面」):
  //   原本只讀 window.BOSS_NAMES / window.JAPAN_ARENA_EXCLUDE,但 const 不掛 window
  //   → 永遠 undefined → 過濾完全失效。現補上 typeof 雙重 fallback + 加 EVENT_ONLY_HEROES 第三層。
  //   白名單:JAPAN_BOSS_HEROES(大天狗/酒吞童子/玉藻前)— 三妖怪英雄版可作為鬥技場選項
  function _arenaGetSelectableHeroes(){
    try{
      // HERO_DB 雙重 fallback
      const _heroDb = (typeof window.HERO_DB !== 'undefined' && window.HERO_DB)
        || (typeof HERO_DB !== 'undefined' ? HERO_DB : null);
      if(!_heroDb) return [];
      // BOSS_NAMES 雙重 fallback
      const _bossArr = (typeof window.BOSS_NAMES !== 'undefined' && Array.isArray(window.BOSS_NAMES))
        ? window.BOSS_NAMES
        : (typeof BOSS_NAMES !== 'undefined' && Array.isArray(BOSS_NAMES) ? BOSS_NAMES : []);
      const _bossSet = new Set(_bossArr);
      // JAPAN_ARENA_EXCLUDE 雙重 fallback
      const _japExc = (typeof window.JAPAN_ARENA_EXCLUDE !== 'undefined' && window.JAPAN_ARENA_EXCLUDE instanceof Set)
        ? window.JAPAN_ARENA_EXCLUDE
        : (typeof JAPAN_ARENA_EXCLUDE !== 'undefined' && JAPAN_ARENA_EXCLUDE instanceof Set ? JAPAN_ARENA_EXCLUDE : new Set());
      // EVENT_ONLY_HEROES 雙重 fallback(v3.13.27 新增:擋小力/幼兒園小孩/巫女)
      const _evtOnly = (typeof window.EVENT_ONLY_HEROES !== 'undefined' && window.EVENT_ONLY_HEROES instanceof Set)
        ? window.EVENT_ONLY_HEROES
        : (typeof EVENT_ONLY_HEROES !== 'undefined' && EVENT_ONLY_HEROES instanceof Set ? EVENT_ONLY_HEROES : new Set());
      // JAPAN_BOSS_HEROES 白名單(三妖怪英雄版可選)
      const _jpBossWL = (typeof window.JAPAN_BOSS_HEROES !== 'undefined' && window.JAPAN_BOSS_HEROES instanceof Set)
        ? window.JAPAN_BOSS_HEROES
        : (typeof JAPAN_BOSS_HEROES !== 'undefined' && JAPAN_BOSS_HEROES instanceof Set ? JAPAN_BOSS_HEROES : new Set());
      const _result = Object.keys(_heroDb).filter(n => {
        if(_jpBossWL.has(n)) return true;       // 白名單放行
        if(_bossSet.has(n))  return false;      // 擋第 1 層 BOSS_NAMES
        if(_japExc.has(n))   return false;      // 擋第 2 層 JAPAN_ARENA_EXCLUDE
        if(_evtOnly.has(n))  return false;      // 擋第 3 層 EVENT_ONLY_HEROES
        return true;
      }).sort();
      try{ console.log('[admin v3.13.27] 鬥技場可選英雄數: ' + _result.length
        + '(總 ' + Object.keys(_heroDb).length + ' 隻,排除 BOSS ' + _bossSet.size
        + ' + 日本菁英 ' + _japExc.size + ' + 活動限定 ' + _evtOnly.size + ' - 白名單 ' + _jpBossWL.size + ')'); }catch(_){}
      return _result;
    }catch(e){ console.warn('[admin _arenaGetSelectableHeroes 例外]', e); return []; }
  }
  const _ARENA_ELEMENT_KEYS = [
    {k:'water', label:'💧 水'}, {k:'fire', label:'🔥 火'}, {k:'wind', label:'🪽 風'},
    {k:'grass', label:'🌿 草'}, {k:'earth', label:'⛰ 土'}, {k:'light', label:'✨ 光'},
    {k:'dark', label:'🌑 暗'},
  ];

  // 渲染 5 套陣容編輯區
  function _arenaRenderEditor(){
    const editor = document.getElementById('_admin-arena-editor');
    if(!editor) return;
    const heroes = _arenaGetSelectableHeroes();

    let html = '';
    for(let i=0; i<5; i++){
      const team = _arenaPresetWorking[i] || _ARENA_PRESET_DEFAULT[i];
      html += `<div style="background:rgba(20,15,40,0.5);border:1.5px solid rgba(180,120,255,0.4);
        border-radius:8px;padding:12px;margin-bottom:10px;">
        <div style="display:flex;gap:8px;align-items:center;margin-bottom:10px;">
          <span style="font-size:14px;font-weight:800;color:#cc99ff;flex-shrink:0;">第 ${i+1} 套</span>
          <input id="_arena-tn-${i}" value="${(team.name||'').replace(/"/g,'&quot;')}" placeholder="[鬥技場預設] 隊名"
            style="flex:1;padding:6px 10px;font-size:13px;background:rgba(20,20,35,0.95);
            border:1.5px solid rgba(180,120,255,0.5);color:#ddc0ff;border-radius:6px;font-family:inherit;">
        </div>
        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;">`;
      for(let j=0; j<4; j++){
        const hSel = (team.heroes && team.heroes[j]) || '';
        const eSel = (team.elements && team.elements[j]) || '';
        html += `<div style="display:flex;flex-direction:column;gap:4px;">
          <select id="_arena-th-${i}-${j}" style="padding:5px;font-size:12px;background:rgba(20,20,35,0.95);
            border:1px solid rgba(180,120,255,0.4);color:#ddc0ff;border-radius:5px;font-family:inherit;cursor:pointer;">
            <option value="">(選英雄)</option>
            ${heroes.map(n => `<option value="${n}" ${n===hSel?'selected':''}>${n}</option>`).join('')}
          </select>
          <select id="_arena-te-${i}-${j}" style="padding:5px;font-size:12px;background:rgba(20,20,35,0.95);
            border:1px solid rgba(180,120,255,0.4);color:#ddc0ff;border-radius:5px;font-family:inherit;cursor:pointer;">
            <option value="">(選元素)</option>
            ${_ARENA_ELEMENT_KEYS.map(e => `<option value="${e.k}" ${e.k===eSel?'selected':''}>${e.label}</option>`).join('')}
          </select>
        </div>`;
      }
      html += `</div></div>`;
    }
    editor.innerHTML = html;
  }

  // 收集編輯區當前內容 → 寫入 _arenaPresetWorking
  function _arenaCollectFromEditor(){
    for(let i=0; i<5; i++){
      const nm = document.getElementById('_arena-tn-' + i);
      if(!nm) continue;
      const team = _arenaPresetWorking[i] || (_arenaPresetWorking[i] = {});
      team.id = team.id || ('sys_' + (i+1));
      team.name = (nm.value || '').trim() || ('[鬥技場預設] 第 ' + (i+1) + ' 套');
      team.heroes = [];
      team.elements = [];
      for(let j=0; j<4; j++){
        const hsel = document.getElementById('_arena-th-' + i + '-' + j);
        const esel = document.getElementById('_arena-te-' + i + '-' + j);
        team.heroes.push(hsel ? hsel.value : '');
        team.elements.push(esel ? esel.value : '');
      }
    }
  }

  // 載入按鈕:從 Firestore arenaSystemTeams/main 讀
  const _arenaLoadBtn = document.getElementById('_admin-arena-load');
  if(_arenaLoadBtn) _arenaLoadBtn.onclick = async () => {
    const status = document.getElementById('_admin-arena-status');
    status.textContent = '載入中…';
    status.style.color = '#aaa';
    try{
      if(!window._fbDb){ throw new Error('Firestore 未就緒'); }
      const { getDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
      const snap = await getDoc(doc(window._fbDb, 'arenaSystemTeams', 'main'));
      if(snap.exists()){
        const data = snap.data();
        if(Array.isArray(data.teams) && data.teams.length){
          _arenaPresetWorking = JSON.parse(JSON.stringify(data.teams.slice(0,5)));
          while(_arenaPresetWorking.length < 5){
            _arenaPresetWorking.push(JSON.parse(JSON.stringify(_ARENA_PRESET_DEFAULT[_arenaPresetWorking.length])));
          }
          status.textContent = '✅ 已從雲端載入 ' + data.teams.length + ' 套(更新於 '
            + (data.updatedAt ? new Date(data.updatedAt).toLocaleString() : '未知') + ')';
          status.style.color = '#88ccff';
        } else {
          _arenaPresetWorking = JSON.parse(JSON.stringify(_ARENA_PRESET_DEFAULT));
          status.textContent = '⚠️ 雲端資料格式異常,已載入內建預設';
          status.style.color = '#ffaa66';
        }
      } else {
        _arenaPresetWorking = JSON.parse(JSON.stringify(_ARENA_PRESET_DEFAULT));
        status.textContent = '📭 雲端無資料,顯示內建預設;編輯後按「儲存」即會首次寫入';
        status.style.color = '#ffaa66';
      }
      _arenaRenderEditor();
    }catch(e){
      console.error('[admin arena load]', e);
      status.textContent = '❌ 載入失敗:' + (e && e.message || '未知錯誤') + ' — 已載入內建預設';
      status.style.color = '#ff8866';
      _arenaPresetWorking = JSON.parse(JSON.stringify(_ARENA_PRESET_DEFAULT));
      _arenaRenderEditor();
    }
  };

  // 還原內建預設按鈕
  const _arenaResetBtn = document.getElementById('_admin-arena-reset');
  if(_arenaResetBtn) _arenaResetBtn.onclick = () => {
    if(!confirm('確定還原為內建 5 套經典陣容?目前編輯中的內容會消失(尚未儲存到雲端的話)。')) return;
    _arenaPresetWorking = JSON.parse(JSON.stringify(_ARENA_PRESET_DEFAULT));
    _arenaRenderEditor();
    const status = document.getElementById('_admin-arena-status');
    if(status){ status.textContent = '🔄 已還原內建預設,記得按「儲存」才會生效'; status.style.color = '#ffaa66'; }
  };

  // 儲存按鈕:寫到 Firestore + 即時套用到當前記憶體
  const _arenaSaveBtn = document.getElementById('_admin-arena-save');
  if(_arenaSaveBtn) _arenaSaveBtn.onclick = async () => {
    const btn = document.getElementById('_admin-arena-save');
    const res = document.getElementById('_admin-arena-save-result');
    btn.disabled = true;
    btn.textContent = '⏳ 儲存中…';
    try{
      // 收集當前編輯內容
      _arenaCollectFromEditor();
      // 驗證:每套必須有 4 英雄(不可空)
      for(let i=0; i<5; i++){
        const t = _arenaPresetWorking[i];
        if(!t.name || !t.name.trim()){ throw new Error('第 ' + (i+1) + ' 套隊名為空'); }
        const emptyHero = t.heroes.findIndex(h => !h);
        if(emptyHero >= 0){ throw new Error('第 ' + (i+1) + ' 套第 ' + (emptyHero+1) + ' 位英雄未選'); }
      }
      // ★ v3.13.27(2026-06-03) — 儲存前三層黑名單嚴驗(防止 GM 不慎存了 BOSS/菁英到雲端)
      const _selectable = new Set(_arenaGetSelectableHeroes());
      for(let i=0; i<5; i++){
        const t = _arenaPresetWorking[i];
        for(let j=0; j<4; j++){
          const hname = t.heroes[j];
          if(!_selectable.has(hname)){
            throw new Error('第 ' + (i+1) + ' 套第 ' + (j+1) + ' 位「' + hname + '」是 BOSS / 菁英 / 活動限定,不可用於鬥技場');
          }
        }
      }
      // 寫到 Firestore
      if(!window._fbDb){ throw new Error('Firestore 未就緒'); }
      // ★ v3.13.27 — 守門:必須是 GM 才能寫(雙保險,Firestore Rules 應該也有擋)
      if(typeof window._isAdminUser !== 'function' || !window._isAdminUser()){
        throw new Error('權限不足:需要 GM 身份(請確認登入 email 在 ADMIN 名單)');
      }
      const { setDoc, doc } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
      const payload = {
        teams: _arenaPresetWorking,
        updatedAt: Date.now(),
        updatedBy: (window._fbUser && window._fbUser.email) || 'unknown',
      };
      // ★ v3.13.27 — 把 payload 印到 console,方便 debug(如果 Firestore 拒絕,可看到實際送什麼)
      try{ console.log('[admin arena save v3.13.27] payload:', JSON.parse(JSON.stringify(payload))); }catch(_){}
      await setDoc(doc(window._fbDb, 'arenaSystemTeams', 'main'), payload);
      // 立即套用到記憶體(讓 GM 自己當下開鬥技場就能看到效果)
      if(typeof window._arenaApplySystemTeamsFromCloud === 'function'){
        window._arenaApplySystemTeamsFromCloud(_arenaPresetWorking);
      }
      res.style.color = '#88ccff';
      res.textContent = '✅ 已儲存到雲端!所有玩家下次抽取鬥技場對手時會套用最新版本。';
    }catch(e){
      // ★ v3.13.27 — 改善錯誤訊息:Firestore 錯誤特別處理
      console.error('[admin arena save]', e);
      let _msg = (e && e.message) || (e && e.code) || '未知錯誤';
      // Firestore permission-denied 特別提示
      if(e && (e.code === 'permission-denied' || /permission/i.test(_msg))){
        _msg = '🔒 Firestore 規則拒絕寫入(權限不足)\n'
             + '原因:目前帳號可能不在 GM 名單(雲端規則層),或 arenaSystemTeams/main 的寫入規則沒開放\n'
             + '解法:確認登入 email 在 ADMIN 名單,或檢查 Firestore Rules 是否含「match /arenaSystemTeams/main { allow write: if isAdmin() }」';
      } else if(e && (e.code === 'unauthenticated' || /unauthenticated/i.test(_msg))){
        _msg = '🔒 未登入或登入逾期,請重新登入後再試';
      } else if(e && (e.code === 'unavailable' || /network|offline/i.test(_msg))){
        _msg = '📡 網路問題,Firestore 連線失敗,請檢查網路再試';
      }
      res.style.color = '#ff6666';
      res.style.whiteSpace = 'pre-wrap';  // ★ v3.13.27 — 允許多行錯誤訊息
      res.textContent = '❌ 儲存失敗:' + _msg;
    }finally{
      btn.disabled = false;
      btn.textContent = '💾 儲存到雲端(對所有玩家即時生效)';
    }
  };

  // 初始渲染(用內建預設填一次,GM 進來就看得到 UI)
  _arenaRenderEditor();
  // ── 鬥技場預設陣容管理 結束 ──

  // ════════════════════════════════════════════════════════════════════════════
  // ★ v3.15.9 — 伺服器休息 / 開機排程 init
  //   Firestore gameConfig/restSchedule { enabled, startHHMM, endHHMM, warnMin, restMessage, warnMessage, updatedAt, updatedBy }
  //   GM 設定後,玩家端 index.html 的 _startRestScheduleWatcher 會即時(onSnapshot + 本機 ticker)套用。
  //   gameConfig = GM-only 寫 / 登入可讀(同 arenaSwitch),不需改 firestore.rules,無安全漏洞。
  // ════════════════════════════════════════════════════════════════════════════
  (function _initRestScheduleSection(){
    const loadBtn   = document.getElementById('_admin-restsched-load');
    const onBtn     = document.getElementById('_admin-restsched-on');
    const offBtn    = document.getElementById('_admin-restsched-off');
    const statusEl  = document.getElementById('_admin-restsched-status');
    const resEl     = document.getElementById('_admin-restsched-result');
    const startEl   = document.getElementById('_admin-restsched-start');
    const endEl     = document.getElementById('_admin-restsched-end');
    const warnEl    = document.getElementById('_admin-restsched-warnmin');
    const restMsgEl = document.getElementById('_admin-restsched-restmsg');
    const warnMsgEl = document.getElementById('_admin-restsched-warnmsg');
    if(!loadBtn || !onBtn || !offBtn){
      console.warn('[admin restsched] DOM 元素缺失,跳過初始化');
      return;
    }
    async function _getSdk(){
      try{
        if(window._fbFns && window._fbFns.setDoc){
          return { getDoc: window._fbFns.getDoc, setDoc: window._fbFns.setDoc, doc: window._fbFns.doc };
        }
        const m = await import('https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore.js');
        return { getDoc: m.getDoc, setDoc: m.setDoc, doc: m.doc };
      }catch(e){
        console.warn('[admin restsched] SDK 取得失敗', e);
        return null;
      }
    }
    // HH:MM 基本驗證(input type=time 一律回傳零補位的 HH:MM,故手動解析即可,不用正則)
    function _validHHMM(s){
      if(typeof s !== 'string') return false;
      const p = s.split(':');
      if(p.length !== 2 || p[1].length !== 2) return false;
      const h = parseInt(p[0], 10), mi = parseInt(p[1], 10);
      return !isNaN(h) && !isNaN(mi) && h >= 0 && h <= 23 && mi >= 0 && mi <= 59;
    }
    async function _loadSched(){
      statusEl.textContent = '載入中...';
      statusEl.style.color = '#aaa';
      try{
        if(!window._fbDb){ throw new Error('Firestore 未就緒'); }
        const sdk = await _getSdk();
        if(!sdk || !sdk.getDoc || !sdk.doc){ throw new Error('Firestore SDK 未就緒'); }
        const snap = await sdk.getDoc(sdk.doc(window._fbDb, 'gameConfig', 'restSchedule'));
        if(snap && snap.exists()){
          const data = snap.data() || {};
          const enabled = (data.enabled === true);
          if(_validHHMM(data.startHHMM) && startEl) startEl.value = data.startHHMM;
          if(_validHHMM(data.endHHMM) && endEl) endEl.value = data.endHHMM;
          if(typeof data.warnMin === 'number' && warnEl) warnEl.value = String(data.warnMin);
          if(typeof data.restMessage === 'string' && data.restMessage && restMsgEl) restMsgEl.value = data.restMessage;
          if(typeof data.warnMessage === 'string' && data.warnMessage && warnMsgEl) warnMsgEl.value = data.warnMessage;
          const updatedAt = data.updatedAt ? new Date(data.updatedAt).toLocaleString() : '(無記錄)';
          const updatedBy = data.updatedBy ? data.updatedBy : '(無記錄)';
          if(enabled){
            statusEl.style.color = '#9aa4ff';
            statusEl.textContent = '🌙 目前:已啟用(休息 ' + (data.startHHMM || '?') + ' → 開機 ' + (data.endHHMM || '?')
              + ',提前 ' + (typeof data.warnMin === 'number' ? data.warnMin : 10) + ' 分預告)。最後更新:' + updatedAt + ' by ' + updatedBy;
          } else {
            statusEl.style.color = '#88dd99';
            statusEl.textContent = '☀ 目前:已停用(不會自動休息)。最後更新:' + updatedAt + ' by ' + updatedBy;
          }
        } else {
          statusEl.style.color = '#88ccff';
          statusEl.textContent = '☁ 雲端尚無排程設定 → 預設停用。設定時間後按「🌙 啟用排程」即生效。';
        }
      }catch(e){
        statusEl.style.color = '#ff6666';
        statusEl.textContent = '❌ 載入失敗:' + (e && e.message || e);
      }
    }
    async function _saveSched(enabled){
      const btn = enabled ? onBtn : offBtn;
      const orig = btn.textContent;
      btn.disabled = true;
      btn.textContent = '處理中...';
      resEl.textContent = '';
      try{
        if(!window._fbDb){ throw new Error('Firestore 未就緒'); }
        const sdk = await _getSdk();
        if(!sdk || !sdk.setDoc || !sdk.doc){ throw new Error('Firestore SDK 未就緒'); }
        const startHHMM = (startEl && startEl.value) || '';
        const endHHMM   = (endEl && endEl.value) || '';
        let warnMin = warnEl ? parseInt(warnEl.value, 10) : 10;
        if(isNaN(warnMin) || warnMin < 0) warnMin = 0;
        if(warnMin > 120) warnMin = 120;
        const restMessage = (restMsgEl && restMsgEl.value) || '';
        const warnMessage = (warnMsgEl && warnMsgEl.value) || '';
        // 啟用時嚴驗:時間格式 + 開始≠開機(相同會造成 24 小時全鎖死)
        if(enabled){
          if(!_validHHMM(startHHMM) || !_validHHMM(endHHMM)){ throw new Error('時間格式錯誤,請用 HH:MM(24 小時制)'); }
          if(startHHMM === endHHMM){ throw new Error('休息開始與開機時間不可相同(否則會 24 小時全鎖死)'); }
        }
        const me = (window._fbAuth && window._fbAuth.currentUser) || null;
        const updatedBy = me ? (me.email || me.uid.slice(0, 10)) : 'unknown';
        await sdk.setDoc(sdk.doc(window._fbDb, 'gameConfig', 'restSchedule'), {
          enabled: !!enabled,
          startHHMM: startHHMM,
          endHHMM: endHHMM,
          warnMin: warnMin,
          restMessage: restMessage,
          warnMessage: warnMessage,
          updatedAt: Date.now(),
          updatedBy: updatedBy,
        });
        resEl.style.color = enabled ? '#9aa4ff' : '#88dd99';
        resEl.textContent = enabled
          ? '🌙 已啟用!休息 ' + startHHMM + ' → 開機 ' + endHHMM + '(提前 ' + warnMin + ' 分預告)。全體玩家約 30 秒內生效。'
          : '☀ 已停用,玩家不會再自動進入休息畫面。約 30 秒內生效。';
        setTimeout(_loadSched, 300);
      }catch(e){
        console.error('[admin restsched save]', e);
        resEl.style.color = '#ff6666';
        resEl.textContent = '❌ 設定失敗:' + (e && e.message || '未知錯誤');
      }finally{
        btn.disabled = false;
        btn.textContent = orig;
      }
    }
    loadBtn.addEventListener('click', _loadSched);
    onBtn.addEventListener('click', function(){ _saveSched(true); });
    offBtn.addEventListener('click', function(){ _saveSched(false); });
    setTimeout(_loadSched, 200);  // 開面板自動載一次
  })();

  // ════════════════════════════════════════════════════════════════════════════
  // ★★ v5.208.0 — 荒島求生 開放設定 init ★★
  //   Firestore gameConfig/islandAccess { open, localOnly, updatedAt, updatedBy }
  //   讀取端:主程式 index.html 的 _lxpsIslAccFetch / _lxpsIslandAdminOnly、
  //          小遊戲 minigame_index.html 的 islAccFetch / islAdminOnly / islLocalOnly。
  //   ⚠ 三個檔案共用同一個 localStorage 快取 key `lxps_island_access_cache`(同 origin),
  //     本卡存檔後順手把快取寫新,讓 GM 自己這台不必等 5 分鐘輪詢就看到新狀態。
  //   ⚠ 未登入訪客也要讀得到這份文件 ⇒ firestore.rules 需放行 islandAccess 未登入讀取
  //     (比照 restSchedule)。沒部署也不會壞,只是訪客一律退回「只有 GM」的保守預設。
  // ════════════════════════════════════════════════════════════════════════════
  (function _initIslandAccessSection(){
    const loadBtn  = document.getElementById('_admin-island-load');
    const saveBtn  = document.getElementById('_admin-island-save');
    const openEl   = document.getElementById('_admin-island-open');
    const localEl  = document.getElementById('_admin-island-localonly');
    const statusEl = document.getElementById('_admin-island-status');
    const resEl    = document.getElementById('_admin-island-result');
    // ★ v5.211.0 三選一模式(測試版/正式版/只有GM)的 radio,底層仍橋接回 openEl/localEl 這兩顆隱藏勾選框,
    //   下面 _loadAcc/_saveAcc 的既有邏輯完全不必改。
    const modeTest     = document.getElementById('_admin-island-mode-test');
    const modeOfficial = document.getElementById('_admin-island-mode-official');
    const modeGmOnly   = document.getElementById('_admin-island-mode-gmonly');
    if(!loadBtn || !saveBtn || !openEl || !localEl){
      console.warn('[admin islandAccess] DOM 元素缺失,跳過初始化');
      return;
    }
    function _modeToChecks(open, localOnly){
      if(!open) return 'gmonly';
      return localOnly ? 'test' : 'official';
    }
    function _paintMode(mode){
      if(modeTest) modeTest.checked = (mode === 'test');
      if(modeOfficial) modeOfficial.checked = (mode === 'official');
      if(modeGmOnly) modeGmOnly.checked = (mode === 'gmonly');
    }
    function _modeChanged(mode){
      // 把三選一的結果寫回隱藏的 open/localOnly 勾選框,_saveAcc 讀的就是這兩顆,不必改它。
      if(mode === 'test'){ openEl.checked = true; localEl.checked = true; }
      else if(mode === 'official'){ openEl.checked = true; localEl.checked = false; }
      else { openEl.checked = false; localEl.checked = false; }
    }
    if(modeTest) modeTest.addEventListener('change', function(){ if(modeTest.checked) _modeChanged('test'); });
    if(modeOfficial) modeOfficial.addEventListener('change', function(){ if(modeOfficial.checked) _modeChanged('official'); });
    if(modeGmOnly) modeGmOnly.addEventListener('change', function(){ if(modeGmOnly.checked) _modeChanged('gmonly'); });
    async function _getSdk(){
      try{
        if(window._fbFns && window._fbFns.setDoc){
          return { getDoc: window._fbFns.getDoc, setDoc: window._fbFns.setDoc, doc: window._fbFns.doc };
        }
        const m = await import('https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore.js');
        return { getDoc: m.getDoc, setDoc: m.setDoc, doc: m.doc };
      }catch(e){
        console.warn('[admin islandAccess] SDK 取得失敗', e);
        return null;
      }
    }
    function _paintStatus(data){
      if(!statusEl) return;
      if(!data){
        statusEl.style.color = '#88ccff';
        statusEl.textContent = '☁ 雲端尚無設定 → 兩端一律退回程式內建預設值(目前＝只有 GM 進得去)。選好模式後按「💾 儲存設定」即生效。';
        _paintMode('gmonly');
        return;
      }
      const open = (data.open === true);
      const lo   = (data.localOnly === true);
      const updatedAt = data.updatedAt ? new Date(data.updatedAt).toLocaleString() : '(無記錄)';
      const updatedBy = data.updatedBy ? data.updatedBy : '(無記錄)';
      const mode = _modeToChecks(open, lo);
      const modeLabel = { test:'🧪 免登入測試版', official:'🔓 登入帳號正式遊玩版', gmonly:'🔒 只有 GM 能進' }[mode];
      statusEl.style.color = open ? '#9fdcff' : '#ffcc88';
      statusEl.textContent = '目前模式:' + modeLabel + '。最後更新:' + updatedAt + ' by ' + updatedBy;
      _paintMode(mode);   /* ★ v5.211.0 進場自動勾對應的那顆 radio,老師一眼就看得出現在是哪個模式 */
    }
    async function _loadAcc(){
      statusEl.textContent = '載入中...';
      statusEl.style.color = '#aaa';
      try{
        if(!window._fbDb){ throw new Error('Firestore 未就緒'); }
        const sdk = await _getSdk();
        if(!sdk || !sdk.getDoc || !sdk.doc){ throw new Error('Firestore SDK 未就緒'); }
        const snap = await sdk.getDoc(sdk.doc(window._fbDb, 'gameConfig', 'islandAccess'));
        if(snap && snap.exists()){
          const data = snap.data() || {};
          openEl.checked  = (data.open === true);
          localEl.checked = (data.localOnly === true);
          _paintStatus(data);
        } else {
          _paintStatus(null);
        }
      }catch(e){
        statusEl.style.color = '#ff6666';
        statusEl.textContent = '❌ 載入失敗:' + (e && e.message || e);
      }
    }
    async function _saveAcc(){
      const orig = saveBtn.textContent;
      saveBtn.disabled = true;
      saveBtn.textContent = '處理中...';
      resEl.textContent = '';
      try{
        if(!window._fbDb){ throw new Error('Firestore 未就緒'); }
        const sdk = await _getSdk();
        if(!sdk || !sdk.setDoc || !sdk.doc){ throw new Error('Firestore SDK 未就緒'); }
        const me = (window._fbAuth && window._fbAuth.currentUser) || null;
        const updatedBy = me ? (me.email || me.uid.slice(0, 10)) : 'unknown';
        const payload = {
          open: !!openEl.checked,
          localOnly: !!localEl.checked,
          updatedAt: Date.now(),
          updatedBy: updatedBy,
        };
        await sdk.setDoc(sdk.doc(window._fbDb, 'gameConfig', 'islandAccess'), payload);
        // GM 自己這台立刻生效(不必等 5 分鐘輪詢):同步記憶體值 + 共用快取 + 重畫首頁那顆按鈕
        try{
          window._LXPS_ISLACC = payload;
          if(typeof window._lxpsIslAccCacheWrite === 'function') window._lxpsIslAccCacheWrite(payload);
          if(typeof window._lxpsSyncIslandBtnState === 'function') window._lxpsSyncIslandBtnState();
        }catch(_){}
        resEl.style.color = '#9fdcff';
        resEl.textContent = (payload.open ? '🔓 已開放給所有玩家' : '🔒 已改為只有 GM 進得去')
          + (payload.localOnly ? '｜📵 進度只留裝置' : '｜☁ 進度存雲端')
          + '。主程式與小遊戲兩端約 5 分鐘內全面生效(玩家重開也會立即讀到)。';
        setTimeout(_loadAcc, 300);
      }catch(e){
        console.error('[admin islandAccess save]', e);
        resEl.style.color = '#ff6666';
        resEl.textContent = '❌ 設定失敗:' + (e && e.message || '未知錯誤');
      }finally{
        saveBtn.disabled = false;
        saveBtn.textContent = orig;
      }
    }
    loadBtn.addEventListener('click', _loadAcc);
    saveBtn.addEventListener('click', _saveAcc);
    setTimeout(_loadAcc, 260);  // 開面板自動載一次
  })();

  // ════════════════════════════════════════════════════════════════════════════
  // ★★ v5.101.0(老師 2026-08-21 需求)— 關卡閘門 init ★★
  //   沿用 index.html 既有單一真相:window._STAGE_GATE_KEYS / _STAGE_GATE_LABEL /
  //   _stageGateOpen(key) 讀 / _fbSetStageGates(map) 寫 / _fbLoadStageGates() 重讀。
  //   ★ 本卡只管勾選與送出,所有雲端邏輯與 fail-open 守門都在 index.html(不做第二套口徑)。
  //   ⚠ 勾選狀態是「本地草稿」,按下【💾 儲存設定】才會寫雲端;重新讀取會丟棄未存的草稿。
  // ════════════════════════════════════════════════════════════════════════════
  (function _initStageGateSection(){
    const listEl   = document.getElementById('_admin-stagegate-list');
    const saveBtn  = document.getElementById('_admin-stagegate-save');
    const reloadBtn= document.getElementById('_admin-stagegate-reload');
    const allOnBtn = document.getElementById('_admin-stagegate-allon');
    const resEl    = document.getElementById('_admin-stagegate-result');
    if(!listEl || !saveBtn || !reloadBtn){
      console.warn('[admin stagegate] DOM 元素缺失,跳過初始化');
      return;
    }
    let _draft = {};   // 本地草稿:key -> bool(true=開放)
    function _keys(){
      try{
        if(Array.isArray(window._STAGE_GATE_KEYS) && window._STAGE_GATE_KEYS.length) return window._STAGE_GATE_KEYS;
      }catch(_){}
      return ['maokong','taiwan','japan','egypt','china','worldboss','arena'];
    }
    function _label(k){
      try{ return (window._STAGE_GATE_LABEL && window._STAGE_GATE_LABEL[k]) || k; }catch(_){ return k; }
    }
    function _syncDraftFromCloud(){
      _draft = {};
      _keys().forEach(function(k){
        let open = true;
        try{ open = (typeof window._stageGateOpen === 'function') ? !!window._stageGateOpen(k) : true; }catch(_){ open = true; }
        _draft[k] = open;
      });
    }
    function _render(){
      let html = '';
      _keys().forEach(function(k){
        const on = (_draft[k] !== false);
        html += '<label style="display:flex;align-items:center;gap:12px;padding:8px 12px;border-radius:8px;cursor:pointer;'
          + 'background:' + (on ? 'rgba(30,70,45,0.5)' : 'rgba(80,30,25,0.5)') + ';'
          + 'border:1px solid ' + (on ? 'rgba(120,220,150,0.5)' : 'rgba(255,140,120,0.6)') + ';">'
          + '<input type="checkbox" data-sg-key="' + k + '"' + (on ? ' checked' : '') + ' style="width:20px;height:20px;cursor:pointer;">'
          + '<span style="flex:1;font-size:16px;font-weight:800;color:#eee;">' + _label(k) + '</span>'
          + '<span style="font-size:14px;font-weight:900;color:' + (on ? '#8fffb0' : '#ff9f8f') + ';">'
          + (on ? '🟢 開放中' : '🔧 維修中') + '</span>'
          + '</label>';
      });
      listEl.innerHTML = html;
      // 勾選只改草稿並即時重繪(不寫雲端)
      Array.prototype.forEach.call(listEl.querySelectorAll('input[data-sg-key]'), function(cb){
        cb.addEventListener('change', function(){
          _draft[cb.getAttribute('data-sg-key')] = !!cb.checked;
          _render();
          if(resEl){ resEl.style.color = '#ffcc88'; resEl.textContent = '⚠ 已修改但尚未儲存 — 請按【💾 儲存設定】才會對學生生效。'; }
        });
      });
    }
    function _reload(){
      if(resEl){ resEl.style.color = '#aaa'; resEl.textContent = '讀取中...'; }
      try{
        if(typeof window._fbLoadStageGates === 'function') window._fbLoadStageGates();
      }catch(_){}
      // _fbLoadStageGates 是非同步且無回傳,延遲一拍再讀 in-memory 結果(讀不到就是全開,不會擋人)
      setTimeout(function(){
        _syncDraftFromCloud();
        _render();
        if(resEl){ resEl.style.color = '#8fffb0'; resEl.textContent = '✅ 已讀取目前設定。'; }
      }, 900);
    }
    saveBtn.addEventListener('click', async function(){
      const closed = _keys().filter(function(k){ return _draft[k] === false; });
      const msg = closed.length
        ? ('確定要把下列關卡切成「維修中」嗎?\n\n' + closed.map(function(k){ return '🔧 ' + _label(k); }).join('\n')
           + '\n\n學生點進去會看到「此關卡尚在維修中,敬請期待」,你(GM)仍可進入測試。\n不會刪除任何進度。')
        : '確定要把「全部關卡」都設為開放嗎?';
      if(!confirm(msg)) return;
      saveBtn.disabled = true; saveBtn.style.opacity = '0.6';
      if(resEl){ resEl.style.color = '#aaa'; resEl.textContent = '設定中...'; }
      let ok = false;
      try{
        if(typeof window._fbSetStageGates === 'function'){
          ok = await Promise.resolve(window._fbSetStageGates(_draft));
        } else {
          throw new Error('主程式尚未載入 _fbSetStageGates(請確認 index.html 同版 v5.101.0)');
        }
      }catch(e){
        ok = false;
        if(resEl){ resEl.style.color = '#ff6666'; resEl.textContent = '❌ 設定失敗:' + ((e && e.message) || e); }
      }
      saveBtn.disabled = false; saveBtn.style.opacity = '1';
      if(ok){
        _syncDraftFromCloud(); _render();
        if(resEl){
          resEl.style.color = '#8fffb0';
          resEl.textContent = closed.length
            ? ('✅ 已儲存 — ' + closed.length + ' 個關卡進入維修中(學生回到關卡頁即刻生效)。')
            : '✅ 已儲存 — 全部關卡開放中。';
        }
      } else if(resEl && resEl.textContent === '設定中...'){
        resEl.style.color = '#ff6666'; resEl.textContent = '❌ 設定失敗,請稍後再試。';
      }
    });
    reloadBtn.addEventListener('click', _reload);
    if(allOnBtn){
      allOnBtn.addEventListener('click', function(){
        _keys().forEach(function(k){ _draft[k] = true; });
        _render();
        if(resEl){ resEl.style.color = '#ffcc88'; resEl.textContent = '⚠ 已全部勾為開放,請按【💾 儲存設定】才會生效。'; }
      });
    }
    _syncDraftFromCloud();
    _render();
    setTimeout(_reload, 300);   // 開面板自動拉一次最新雲端設定
  })();

  // ════════════════════════════════════════════════════════════════════════════
  // ★ v4.21.0 — 寵物系統開關 init(由寵物小屋內移來)
  //   沿用 index.html 既有:window._petSysPublicOpen() 讀當前是否對全體開放、
  //   window._fbSetPetSysSwitch(bool) 寫雲端 gameConfig/petSystemSwitch(免改 firestore.rules)。
  //   狀態於「回到關卡頁」時由 _fbLoadPetSysSwitch 拉一次;此處「🔄 重新讀取」再拉一次確保最新。
  // ════════════════════════════════════════════════════════════════════════════
  (function _initPetSysSection(){
    const statusEl = document.getElementById('_admin-petsys-status');
    const reloadBtn = document.getElementById('_admin-petsys-reload');
    const openBtn  = document.getElementById('_admin-petsys-open');
    const closeBtn = document.getElementById('_admin-petsys-close');
    const resEl    = document.getElementById('_admin-petsys-result');
    if(!statusEl || !openBtn || !closeBtn){
      console.warn('[admin petsys] DOM 元素缺失,跳過初始化');
      return;
    }
    function _renderStatus(){
      let pub = null;
      try{
        if(typeof window._petSysPublicOpen === 'function') pub = !!window._petSysPublicOpen();
      }catch(_){ pub = null; }
      if(pub === true){
        statusEl.style.color = '#8fffb0';
        statusEl.textContent = '🟢 目前:已對【全體玩家】開放 — 所有學生皆可使用寵物系統。';
      } else if(pub === false){
        statusEl.style.color = '#ff9e9e';
        statusEl.textContent = '🔴 目前:暫時關閉(僅 GM 測試)— 學生看不到、也用不到寵物系統(資料保留)。';
      } else {
        statusEl.style.color = '#ffd27f';
        statusEl.textContent = '⚠ 讀不到目前狀態(可能剛進後台雲端開關尚未載入)。請按「🔄 重新讀取狀態」。';
      }
    }
    function _reload(){
      try{
        if(typeof window._fbLoadPetSysSwitch === 'function') window._fbLoadPetSysSwitch();
      }catch(_){}
      // _fbLoadPetSysSwitch 是非同步 getDoc;稍候再讀一次記憶體旗標(不阻塞、best-effort)
      statusEl.style.color = '#aaa';
      statusEl.textContent = '重新讀取中...';
      setTimeout(_renderStatus, 900);
      setTimeout(_renderStatus, 2200);
    }
    async function _setSwitch(open){
      const btn = open ? openBtn : closeBtn;
      const orig = btn.textContent;
      const msg = open
        ? '確定要把「寵物系統」對【全體玩家】開放嗎?\n所有學生下次登入(或回到關卡頁)後即可使用寵物小屋、馴養、召喚寵物等功能。'
        : '確定要把「寵物系統」暫時關閉嗎?\n關閉後只有你(GM)能測試,學生看不到、也用不到;不會刪除任何寵物資料。';
      if(!confirm(msg)) return;
      btn.disabled = true; btn.style.opacity = '0.6';
      if(resEl){ resEl.style.color = '#aaa'; resEl.textContent = '設定中...'; }
      let ok = false;
      try{
        if(typeof window._fbSetPetSysSwitch === 'function'){
          ok = await Promise.resolve(window._fbSetPetSysSwitch(open));
        } else {
          throw new Error('主程式尚未載入 _fbSetPetSysSwitch(請確認 index.html 同版 v4.21.0)');
        }
      }catch(e){
        ok = false;
        if(resEl){ resEl.style.color = '#ff6666'; resEl.textContent = '❌ 設定失敗:' + (e && e.message || e); }
      }
      btn.disabled = false; btn.style.opacity = '1'; btn.textContent = orig;
      if(ok){
        if(resEl){
          resEl.style.color = '#88dd99';
          resEl.textContent = open
            ? '✅ 已對全體開放!學生下次登入(或回到關卡頁)即可使用寵物系統。'
            : '✅ 已暫時關閉(僅 GM 可測試),學生看不到寵物系統(資料保留)。';
        }
        _renderStatus();
      } else if(resEl && !resEl.textContent.startsWith('❌')){
        resEl.style.color = '#ff6666';
        resEl.textContent = '⚠ 設定失敗,請檢查網路後再試一次。';
      }
    }
    if(reloadBtn) reloadBtn.addEventListener('click', _reload);
    openBtn.addEventListener('click', function(){ _setSwitch(true); });
    closeBtn.addEventListener('click', function(){ _setSwitch(false); });
    setTimeout(_renderStatus, 200);  // 開面板自動顯示目前狀態
  })();

  // ════════════════════════════════════════════════════════════════════════════
  // ════════════════════════════════════════════════════════════════
  // ★ v5.135.0 — 「🎫 召喚卷編號稽核」卡(三點同步·純讀取零寫入)
  // ────────────────────────────────────────────────────────────────
  //   後端:window._fbAdminReadPlayerTickets(query)  在 index.html v5.135.0
  //   ★ 三槽都讀並套用與玩家端**完全同一套**合併規則(inst union → used union
  //     → un 取 max → inst \ used),否則 GM 看到的數字會和學生登入後不一樣。
  //   ★ 本檔零 optional chaining(鐵律 1.47/1.140)。
  (function _initTicketAuditCard(){
    function _byId(id){ return document.getElementById(id); }
    var _boot = setInterval(function(){
      var qEl = _byId('_admin-ticket-query');
      if(!qEl) return;
      clearInterval(_boot);
      var btn = _byId('_admin-ticket-search');
      var statusEl = _byId('_admin-ticket-status');
      var resEl = _byId('_admin-ticket-result');
      if(!btn || !statusEl || !resEl) return;

      function _esc(t){
        return String(t == null ? '' : t)
          .split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
      }
      function _ts(n){
        if(!n) return '—';
        try{
          var d = new Date(n);
          return (d.getMonth() + 1) + '/' + d.getDate() + ' '
               + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
        }catch(_){ return '—'; }
      }
      var _SRC_LABEL = {
        'legacy':     '舊制券(查無取得紀錄·已合法化)',
        'grant':      '一般取得',
        'gm_reward':  '老師課堂獎勵',
        'admin_grant':'GM 直接發放'
      };

      function _render(data){
        if(!data){ resEl.innerHTML = ''; return; }
        var who = _esc(data.nickname || '(無暱稱)') + ' · ' + _esc(data.email || data.uid);
        var roster = '';
        try{
          if(typeof window._getRosterEntry === 'function' && typeof window._formatRosterLabel === 'function'){
            var re = window._getRosterEntry(data.email || '');
            if(re) roster = ' · ' + _esc(window._formatRosterLabel(re));
          }
        }catch(_){}

        var h = '';
        h += '<div style="background:rgba(0,0,0,0.4);border-radius:8px;padding:10px 12px;margin-bottom:10px;line-height:1.8;">';
        h += '<div style="font-size:15px;font-weight:800;color:#ddccff;">' + who + roster + '</div>';
        h += '<div style="color:#9fe8ff;">目前持有 <b>' + data.heldCount + '</b> 張券'
           + ' · 歷來已用 <b>' + data.usedCount + '</b> 張'
           + (data.legacyCount ? (' · <span style="color:#ffaa88;">其中舊制券 ' + data.legacyCount + ' 張</span>') : '')
           + '</div>';
        h += '<div style="color:' + (data.migrated ? '#88dd99' : '#ffcc66') + ';">'
           + (data.migrated ? '✅ 已完成券編號建檔' : '⏳ 尚未建檔(該生自 v5.135.0 起還沒登入過;首次登入會自動把現有券補上編號)')
           + '</div>';
        h += '<div style="color:#888;font-size:12px;">有券資料的存檔槽:' + (data.slots && data.slots.length ? _esc(data.slots.join(' / ')) : '(無)') + '</div>';
        h += '</div>';

        // 逐券種對帳表
        if(data.rows && data.rows.length){
          h += '<div style="font-size:14px;font-weight:800;color:#c8b4ff;margin:10px 0 6px;">📊 逐券種對帳</div>';
          h += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:13px;">';
          h += '<tr style="background:rgba(120,90,200,0.25);color:#e0d4ff;">'
             + '<th style="padding:6px 8px;text-align:left;">券種</th>'
             + '<th style="padding:6px 8px;">背包</th>'
             + '<th style="padding:6px 8px;">持有實例</th>'
             + '<th style="padding:6px 8px;">歷來使用</th>'
             + '<th style="padding:6px 8px;">需補</th>'
             + '<th style="padding:6px 8px;">舊制券</th></tr>';
          data.rows.forEach(function(r){
            var pc = (r.pending > 0) ? '#ffcc66' : '#88dd99';
            h += '<tr style="border-bottom:1px solid rgba(255,255,255,0.08);">'
               + '<td style="padding:6px 8px;color:#e8e0ff;">' + _esc(r.icon + ' ' + r.name) + '</td>'
               + '<td style="padding:6px 8px;text-align:center;color:#cfe0ff;">' + r.bag + '</td>'
               + '<td style="padding:6px 8px;text-align:center;color:#cfe0ff;font-weight:800;">' + r.held + '</td>'
               + '<td style="padding:6px 8px;text-align:center;color:#aab8d0;">' + r.used + '</td>'
               + '<td style="padding:6px 8px;text-align:center;color:' + pc + ';font-weight:800;">' + r.pending + '</td>'
               + '<td style="padding:6px 8px;text-align:center;color:' + (r.legacy ? '#ffaa88' : '#666') + ';">' + (r.legacy || '—') + '</td>'
               + '</tr>';
          });
          h += '</table></div>';
        }

        // 逐張明細
        if(data.items && data.items.length){
          h += '<div style="font-size:14px;font-weight:800;color:#c8b4ff;margin:14px 0 6px;">🎫 逐張券編號明細(目前持有)</div>';
          h += '<div style="max-height:320px;overflow:auto;background:rgba(0,0,0,0.3);border-radius:8px;padding:8px;">';
          data.items.forEach(function(it){
            var srcTxt = _SRC_LABEL[it.src] || it.src;
            h += '<div style="padding:6px 8px;border-bottom:1px solid rgba(255,255,255,0.06);line-height:1.6;">'
               + '<span style="color:#e8e0ff;font-weight:800;">' + _esc(it.icon + ' ' + it.name) + '</span>'
               + (it.isGm ? ' <span style="color:#ffcf6a;font-size:12px;">🎁GM</span>' : '')
               + (it.legacy ? ' <span style="color:#ffaa88;font-size:12px;font-weight:800;">⚠舊制券</span>' : '')
               + '<br><span style="font-family:monospace;color:#9fe8ff;font-size:12px;">' + _esc(it.tid) + '</span>'
               + ' <span style="color:#888;font-size:12px;">· ' + _esc(srcTxt) + ' · ' + _ts(it.at) + '</span>'
               + '</div>';
          });
          h += '</div>';
        } else {
          h += '<div style="color:#999;padding:10px;">目前沒有持有任何召喚卷。</div>';
        }
        resEl.innerHTML = h;
      }

      async function _doSearch(){
        var q = String(qEl.value || '').trim();
        if(!q){ statusEl.style.color = '#ffd27f'; statusEl.textContent = '⚠ 請先輸入 email、學號或 uid。'; return; }
        statusEl.style.color = '#aaa'; statusEl.textContent = '查詢中...';
        resEl.innerHTML = '';
        try{
          if(typeof window._fbAdminReadPlayerTickets !== 'function'){
            throw new Error('主程式尚未載入 _fbAdminReadPlayerTickets(請確認 index.html 同版 v5.135.0)');
          }
          var data = await window._fbAdminReadPlayerTickets(q);
          statusEl.style.color = '#88dd99';
          statusEl.textContent = '✅ 查詢完成(純讀取,未更動任何資料)。';
          _render(data);
        }catch(e){
          statusEl.style.color = '#ff6666';
          statusEl.textContent = '❌ 查詢失敗:' + (e && e.message ? e.message : e);
        }
      }
      btn.addEventListener('click', _doSearch);
      qEl.addEventListener('keydown', function(ev){ if(ev && ev.key === 'Enter') _doSearch(); });
    }, 400);
    setTimeout(function(){ clearInterval(_boot); }, 30000);
  })();

  // ★ v5.32.0 — 「🛡️ 裝備管理」卡(裝備 Phase 4 後半 GM 工具·三點同步)
  //   後端三函式在 index.html v5.32.0:
  //     window._fbAdminReadPlayerGear(query)      查詢(email/lsps學號/uid → 主檔最新)
  //     window._fbAdminGearGrantForUid(uid, iid)  發放(roll 詞條·三槽同寫·admin_grant·通知)
  //     window._fbAdminGearDeleteForUid(uid, eq)  刪除(三槽同寫·admin_delete 不復活·通知)
  //   下拉查表 window._fbAdminGearDbList()(60 件·admin_panel 讀不到 GEAR_DB const)。
  //   無真 optional chaining(老 Safari iPad 相容)。
  // ════════════════════════════════════════════════════════════════════════════
  (function _initGearAdminSection(){
    var queryEl  = document.getElementById('_admin-gear-query');
    var searchBtn = document.getElementById('_admin-gear-search');
    var statusEl = document.getElementById('_admin-gear-status');
    var grantBox = document.getElementById('_admin-gear-grantbox');
    var slotSel  = document.getElementById('_admin-gear-slot-sel');
    var itemSel  = document.getElementById('_admin-gear-item-sel');
    var grantBtn = document.getElementById('_admin-gear-grant-btn');
    var resEl    = document.getElementById('_admin-gear-result');
    if(!queryEl || !searchBtn || !resEl){
      console.warn('[admin gear] DOM 元素缺失,跳過初始化');
      return;
    }
    var _esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
    var _curUid = '';         // 目前查詢到的玩家 uid(發放/刪除都對這位)
    var _dbList = null;       // GEAR_DB 60 件摘要快取(讀自 index 橋接)
    var SLOT_LABELS = { head:'🪖 頭部', body:'🧥 身軀', main:'🔨 主手', off:'🛡️ 副手', legs:'👟 腿部', acc:'🏅 飾品' };
    var SLOT_ORDER  = ['head','body','main','off','legs','acc'];
    var SRC_LABEL = { summon:'召喚星空', shop:'超商購買', gift:'好友贈送', admin_grant:'老師發放',
                      gm_grant:'GM測試發放', drop_mini:'小怪掉落', drop_rare:'特殊小怪掉落',
                      drop_boss:'BOSS掉落', boss:'BOSS掉落', mini:'小怪掉落', rare:'特殊小怪掉落',
                      tutorial:'教學補發' };
    function _srcTxt(s){ return SRC_LABEL[s] || _esc(s || '?'); }
    function _dateTxt(at){
      try{ if(!at) return '?'; var d = new Date(at);
        return (d.getMonth()+1) + '/' + d.getDate() + ' ' + ('0'+d.getHours()).slice(-2) + ':' + ('0'+d.getMinutes()).slice(-2);
      }catch(_){ return '?'; }
    }
    function _ensureDbList(){
      if(_dbList && _dbList.length) return _dbList;
      try{ if(typeof window._fbAdminGearDbList === 'function') _dbList = window._fbAdminGearDbList(); }catch(_){ _dbList = null; }
      return _dbList || [];
    }
    function _fillSlotSel(){
      var html = '';
      SLOT_ORDER.forEach(function(sl){ html += '<option value="' + sl + '">' + SLOT_LABELS[sl] + '</option>'; });
      slotSel.innerHTML = html;
    }
    function _fillItemSel(){
      var sl = slotSel.value || 'head';
      var list = _ensureDbList().filter(function(x){ return x.slot === sl; });
      var html = '';
      list.forEach(function(x){
        html += '<option value="' + _esc(x.itemId) + '">' + _esc(x.icon) + ' ' + _esc(x.n)
              + '(' + _esc(x.rn) + '·' + _esc(x.baseTxt) + ')</option>';
      });
      itemSel.innerHTML = html || '<option value="">(讀不到裝備資料表)</option>';
    }
    function _renderData(data){
      _curUid = data.uid || '';
      statusEl.style.color = '#9ec8ff';
      statusEl.innerHTML = '👤 <b>' + _esc(data.nickname || '(無暱稱)') + '</b>'
        + ' ・ ' + _esc(data.email || '(無 email)')
        + ' ・ uid <span style="opacity:0.75;">' + _esc(String(data.uid).slice(0, 12)) + '…</span>'
        + ' ・ 持有 <b style="color:' + (data.count >= 100 ? '#ff9e9e' : '#aef0c0') + ';">' + data.count + '</b> / 100 件'
        + (data.count >= 100 ? '(<b style="color:#ff9e9e;">已滿</b>·GM 發放仍可超額)' : '');
      grantBox.style.display = 'block';
      // 依部位分組列出實例
      var bySlot = {};
      (data.items || []).forEach(function(it){ (bySlot[it.slot] = bySlot[it.slot] || []).push(it); });
      var html = '';
      SLOT_ORDER.forEach(function(sl){
        var arr = bySlot[sl];
        if(!arr || !arr.length) return;
        arr.sort(function(a, b){ return (b.at || 0) - (a.at || 0); });
        html += '<div style="margin:10px 0 4px;font-size:14px;font-weight:800;color:#9ec8ff;">'
              + SLOT_LABELS[sl] + '(' + arr.length + ' 件)</div>';
        arr.forEach(function(it){
          var afHtml = (it.affixLines || []).map(function(t){ return '<span style="color:#aaddff;">◆ ' + _esc(t) + '</span>'; }).join('　');
          html += '<div style="border-top:1px solid rgba(140,180,255,0.18);padding:6px 2px;font-size:13px;line-height:1.6;">'
            + '<span style="color:' + _esc(it.rc) + ';font-weight:800;">' + _esc(it.icon) + ' ' + _esc(it.n)
            + ' <span style="font-size:11px;opacity:0.85;">[' + _esc(it.rn) + ']</span></span>'
            + (it.equippedTo ? ' <span style="color:#ffd27f;">⚔ 裝備中:' + _esc(it.equippedTo) + '</span>' : ' <span style="color:#8898b0;">(背包)</span>')
            + (it.gifted ? ' <span style="color:#ff9ac0;font-size:11px;">🎁受贈品</span>' : '')
            + ' <span style="color:#8898b0;font-size:11px;">來源:' + _srcTxt(it.src) + '・' + _dateTxt(it.at)
            + (it.rr2 > 0 ? '・重Roll×' + it.rr2 : '') + '</span>'
            + ' <button class="_gear-del-btn" data-equid="' + _esc(it.eqUid) + '" data-name="' + _esc(it.n) + '"'
            + ' style="float:right;padding:3px 10px;font-size:12px;font-weight:800;background:rgba(255,90,90,0.15);'
            + 'border:1px solid rgba(255,120,120,0.6);color:#ff9e9e;border-radius:6px;cursor:pointer;font-family:inherit;">🗑 刪除</button>'
            + '<br><span style="color:#c8d8ee;">基礎:' + _esc(it.baseTxt || '—') + '</span>'
            + (afHtml ? ('<br>' + afHtml) : '')
            + '</div>';
        });
      });
      if(!html) html = '<div style="text-align:center;color:#9a9aac;padding:12px;">這位學生目前沒有任何裝備。</div>';
      // 帳本(近 40 筆·最新在上;admin_delete/sold/gift_sent 特別標色)
      var led = Array.isArray(data.ledger) ? data.ledger.slice() : [];
      led.sort(function(a, b){ return (b.at || 0) - (a.at || 0); });
      var ledHtml = '';
      led.slice(0, 40).forEach(function(e){
        if(!e) return;
        var sTag = String(e.source || '');
        var col = '#a8c0d8', act = '取得(' + _srcTxt(e.src) + ')';
        if(sTag === 'admin_delete'){ col = '#ff9e9e'; act = '🗑 老師刪除' + (e.removedBy ? '(' + _esc(e.removedBy) + ')' : ''); }
        else if(sTag === 'sold'){ col = '#ffd27f'; act = '💰 賣出'; }
        else if(sTag === 'gift_sent'){ col = '#ff9ac0'; act = '🎁 送給好友'; }
        else if(e.src === 'admin_grant'){ col = '#aef0c0'; act = '🎁 老師發放' + (e.grantedBy ? '(' + _esc(e.grantedBy) + ')' : ''); }
        var _iidDef = _ensureDbList().filter(function(x){ return x.itemId === e.itemId; })[0];
        ledHtml += '<div style="border-top:1px solid rgba(140,180,255,0.12);padding:3px 2px;font-size:12px;color:' + col + ';">'
          + _dateTxt(e.at) + '・' + (_iidDef ? (_esc(_iidDef.icon) + ' ' + _esc(_iidDef.n)) : _esc(e.itemId || '?'))
          + '・' + act
          + (e.giftFrom ? '・來自 ' + _esc(e.giftFrom) : '')
          + ' <span style="opacity:0.55;">' + _esc(String(e.eqUid || '').slice(0, 14)) + '</span>'
          + '</div>';
      });
      html += '<div style="margin-top:12px;font-size:14px;font-weight:800;color:#9ec8ff;">📜 裝備帳本(近 ' + Math.min(led.length, 40) + ' 筆/共 ' + led.length + ' 筆)</div>'
        + (ledHtml || '<div style="color:#8898b0;font-size:12px;padding:6px 2px;">(無帳本紀錄)</div>');
      resEl.innerHTML = html;
      // 逐件刪除 wiring
      var btns = resEl.querySelectorAll('._gear-del-btn');
      for(var i = 0; i < btns.length; i++){
        (function(btn){
          btn.addEventListener('click', function(){ _doDelete(btn.getAttribute('data-equid'), btn.getAttribute('data-name')); });
        })(btns[i]);
      }
    }
    async function _doSearch(){
      var q = String(queryEl.value || '').trim();
      if(!q){ statusEl.style.color = '#ffd27f'; statusEl.textContent = '⚠ 請先輸入 email、學號或 uid。'; return; }
      statusEl.style.color = '#aaa'; statusEl.textContent = '查詢中...';
      resEl.innerHTML = ''; grantBox.style.display = 'none'; _curUid = '';
      try{
        if(typeof window._fbAdminReadPlayerGear !== 'function') throw new Error('主程式尚未載入 _fbAdminReadPlayerGear(請確認 index.html 同版 v5.32.0)');
        var data = await window._fbAdminReadPlayerGear(q);
        _renderData(data);
      }catch(e){
        statusEl.style.color = '#ff6666';
        statusEl.textContent = '❌ 查詢失敗:' + (e && e.message ? e.message : e);
      }
    }
    async function _doGrant(){
      if(!_curUid){ alert('請先查詢學生。'); return; }
      var iid = String(itemSel.value || '');
      if(!iid){ alert('請選擇要發放的裝備。'); return; }
      var picked = _ensureDbList().filter(function(x){ return x.itemId === iid; })[0];
      var nm = picked ? (picked.icon + ' ' + picked.n + '(' + picked.rn + ')') : iid;
      if(!confirm('確定要發放 ' + nm + ' ×1 給這位學生嗎?\n\n・詞條會在發放當下隨機 roll(規則同玩家取得)並永久固定\n・寫入帳本 admin_grant(合法紀錄·不會被稽核回收)\n・會寄登入通知給學生')) return;
      grantBtn.disabled = true; grantBtn.style.opacity = '0.6';
      try{
        if(typeof window._fbAdminGearGrantForUid !== 'function') throw new Error('主程式尚未載入 _fbAdminGearGrantForUid(請確認 index.html 同版 v5.32.0)');
        var r = await window._fbAdminGearGrantForUid(_curUid, iid);
        if(r && r.ok){
          alert('✅ 已發放「' + r.name + '」×1(詞條 ' + r.affixN + ' 條·寫入 ' + (r.wrote || []).join('/') + ')!\n學生下次登入(或在線自動重載)即可看到,並已寄登入通知。');
          _doSearch();
        } else {
          alert('⚠ 發放失敗:' + ((r && r.msg) || '未知錯誤'));
        }
      }catch(e){ alert('❌ 發放失敗:' + (e && e.message ? e.message : e)); }
      grantBtn.disabled = false; grantBtn.style.opacity = '1';
    }
    async function _doDelete(eqUid, name){
      if(!_curUid || !eqUid) return;
      if(!confirm('確定要「永久刪除」這位學生的裝備「' + (name || '?') + '」嗎?\n(實例碼 ' + String(eqUid).slice(0, 14) + '…)\n\n・三槽同寫 + 帳本 admin_delete → 不會復活\n・若正裝備在夥伴身上會自動卸下\n・會寄登入通知給學生(此操作不補償)')) return;
      statusEl.style.color = '#aaa'; statusEl.textContent = '刪除中...';
      try{
        if(typeof window._fbAdminGearDeleteForUid !== 'function') throw new Error('主程式尚未載入 _fbAdminGearDeleteForUid(請確認 index.html 同版 v5.32.0)');
        var r = await window._fbAdminGearDeleteForUid(_curUid, eqUid);
        if(r && r.ok){
          alert('✅ 已刪除「' + r.name + '」(寫入 ' + (r.wrote || []).join('/') + '·帳本 admin_delete)。已寄登入通知。');
        } else {
          alert('⚠ 刪除未執行:' + ((r && r.msg) || '未知原因'));
        }
      }catch(e){ alert('❌ 刪除失敗:' + (e && e.message ? e.message : e)); }
      _doSearch();
    }
    _fillSlotSel();
    _fillItemSel();
    slotSel.addEventListener('change', _fillItemSel);
    searchBtn.addEventListener('click', _doSearch);
    queryEl.addEventListener('keydown', function(ev){ if(ev && ev.key === 'Enter') _doSearch(); });
    grantBtn.addEventListener('click', _doGrant);
    // 面板初開時 index 裝備 block 可能尚未就緒 → 開卡時再補填一次下拉(best-effort)
    setTimeout(function(){ if(!(_dbList && _dbList.length)){ _dbList = null; _fillItemSel(); } }, 1500);
  })();

  // ════════════════════════════════════════════════════════════════════════════
  // ★ v5.16.0 — 動態題庫擴充 init(動態內容層第一期)
  //   雲端結構:dynamicContent/_index = { quizVer, quizPacks:[], quizNextId }
  //             dynamicContent/quiz_N = { list:[{id,grade,subject,difficulty,question,options,answer,hint}] }
  //   規則:讀=登入玩家;寫=isAdmin(firestore.rules v5.16.0 條款,需部署一次)。
  //   id 自 quizNextId(100001 起)單調配發永不重用;每包上限 1800 題防 1MB 文件上限。
  //   發佈成功後呼叫 window._dynContentSync(true) → GM 自己這台立即生效可試玩驗證。
  //   無真 optional chaining(老 Safari iPad 相容)。
  // ════════════════════════════════════════════════════════════════════════════
  (function _initDynQuizSection(){
    var statusEl  = document.getElementById('_admin-dynquiz-status');
    var reloadBtn = document.getElementById('_admin-dynquiz-reload');
    var addBtn    = document.getElementById('_admin-dynquiz-add');
    var parseBtn  = document.getElementById('_admin-dynquiz-parse');
    var pubBtn    = document.getElementById('_admin-dynquiz-publish');
    var clrBtn    = document.getElementById('_admin-dynquiz-clearpending');
    var delBtn    = document.getElementById('_admin-dynquiz-delete');
    var pendEl    = document.getElementById('_admin-dynquiz-pending');
    var listEl    = document.getElementById('_admin-dynquiz-list');
    var filterEl  = document.getElementById('_admin-dynquiz-filter');
    var resEl     = document.getElementById('_admin-dynquiz-result');
    if(!statusEl || !reloadBtn || !pubBtn){
      console.warn('[admin dynquiz] DOM 元素缺失,跳過初始化');
      return;
    }
    var PACK_MAX = 1800;                 // 每包題數上限(約 550~700KB,遠低於 Firestore 1MB 文件上限)
    var ID_START = 100001;               // 動態題起始 id(靜態題庫最大 34694,永不相撞)
    var GRADES = ['低年級','中年級','高年級'];
    var DIFFS  = ['沒自信','普通','我很會'];

    var _cloudIdx = null;                // 最近一次讀到的 _index
    var _cloudList = [];                 // 最近一次讀到的全部已發佈動態題
    var _pending = [];                   // 待發佈(尚未寫入雲端,無 id)

    function _esc(t){
      return String(t === undefined || t === null ? '' : t)
        .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }
    function _say(msg, ok){
      if(resEl) resEl.innerHTML = '<span style="color:' + (ok ? '#8fffb0' : '#ff9a9a') + ';">' + msg + '</span>';
    }
    function _fb(){
      var db = window._fbDb, F = window._fbFns;
      if(!db || !F){ _say('❌ Firestore 未就緒,請先在遊戲主頁登入 GM 帳號。', false); return null; }
      return { db: db, F: F };
    }

    // ── 驗證一題(回傳錯誤字串或 null)──
    function _validate(q){
      if(!q || typeof q !== 'object') return '不是物件';
      if(GRADES.indexOf(String(q.grade)) === -1) return '年級必須是:低年級/中年級/高年級';
      if(!q.subject || !String(q.subject).trim()) return '科目不可空白';
      if(DIFFS.indexOf(String(q.difficulty)) === -1) return '難度必須是:沒自信/普通/我很會';
      if(!q.question || !String(q.question).trim()) return '題目不可空白';
      if(!Array.isArray(q.options) || q.options.length !== 4) return '選項必須恰 4 個';
      for(var i = 0; i < 4; i++){
        if(!q.options[i] || !String(q.options[i]).trim()) return '選項 ' + 'ABCD'[i] + ' 不可空白';
      }
      if(['A','B','C','D'].indexOf(q.answer) === -1) return '答案必須是 A/B/C/D';
      return null;
    }
    function _norm(q){
      return {
        grade: String(q.grade).trim(), subject: String(q.subject).trim(),
        difficulty: String(q.difficulty).trim(), question: String(q.question).trim(),
        options: [String(q.options[0]).trim(), String(q.options[1]).trim(), String(q.options[2]).trim(), String(q.options[3]).trim()],
        answer: q.answer, hint: String(q.hint || '').trim()
      };
    }

    // ── 讀雲端現況 ──
    async function _loadCloud(silent){
      var h = _fb(); if(!h) return false;
      try{
        if(!silent) statusEl.innerHTML = '⏳ 讀取中…';
        var idxSnap = await h.F.getDoc(h.F.doc(h.db, 'dynamicContent', '_index'));
        _cloudIdx = idxSnap.exists() ? (idxSnap.data() || {}) : { quizVer: 0, quizPacks: [], quizNextId: ID_START };
        if(typeof _cloudIdx.quizNextId !== 'number' || _cloudIdx.quizNextId < ID_START) _cloudIdx.quizNextId = ID_START;
        if(!Array.isArray(_cloudIdx.quizPacks)) _cloudIdx.quizPacks = [];
        _cloudList = [];
        for(var i = 0; i < _cloudIdx.quizPacks.length; i++){
          var pSnap = await h.F.getDoc(h.F.doc(h.db, 'dynamicContent', String(_cloudIdx.quizPacks[i])));
          if(pSnap.exists()){
            var pd = pSnap.data();
            if(pd && Array.isArray(pd.list)) _cloudList = _cloudList.concat(pd.list);
          }
        }
        _renderStatus(); _renderList(); _renderSubjectDatalist();
        return true;
      }catch(e){
        statusEl.innerHTML = '❌ 讀取失敗:' + _esc(e && e.message ? e.message : e) +
          '<br><span style="font-size:12px;color:#fa8;">若訊息含 permission,代表 firestore.rules 尚未部署 v5.16.0 的 dynamicContent 條款。</span>';
        return false;
      }
    }
    function _renderStatus(){
      var bySub = {};
      for(var i = 0; i < _cloudList.length; i++){
        var s = _cloudList[i].subject || '(無科目)';
        bySub[s] = (bySub[s] || 0) + 1;
      }
      var subs = Object.keys(bySub).sort().map(function(k){ return _esc(k) + ' ' + bySub[k] + ' 題'; }).join('、');
      var verStr = _cloudIdx.quizVer ? new Date(_cloudIdx.quizVer).toLocaleString('zh-TW') : '(從未發佈)';
      statusEl.innerHTML = '📦 已發佈動態題:<b style="color:#9fe;">' + _cloudList.length + '</b> 題' +
        '(' + _cloudIdx.quizPacks.length + ' 包)・最後發佈:' + _esc(verStr) +
        (subs ? '<br>科目分布:' + subs : '');
    }
    function _renderSubjectDatalist(){
      var dl = document.getElementById('_admin-dynquiz-subject-list');
      if(!dl) return;
      var set = {};
      try{
        if(Array.isArray(window.ADV_QUIZ_DB)){
          for(var i = 0; i < window.ADV_QUIZ_DB.length; i++){
            var q = window.ADV_QUIZ_DB[i];
            if(q && q.subject) set[q.subject] = 1;
          }
        }
      }catch(_e){}
      dl.innerHTML = Object.keys(set).sort().map(function(s){ return '<option value="' + _esc(s) + '">'; }).join('');
    }

    // ── 待發佈清單 ──
    function _renderPending(){
      if(!_pending.length){ pendEl.innerHTML = '(空)'; return; }
      pendEl.innerHTML = _pending.map(function(q, i){
        return '<div style="border-bottom:1px dashed #445;padding:4px 0;">' +
          '<button data-pi="' + i + '" class="_dq-pend-rm" style="float:right;background:none;border:1px solid #d66;color:#faa;border-radius:5px;cursor:pointer;font-family:inherit;padding:1px 7px;">移除</button>' +
          '<b>' + (i + 1) + '.</b>【' + _esc(q.grade) + '・' + _esc(q.subject) + '・' + _esc(q.difficulty) + '】' + _esc(q.question) +
          '<br><span style="color:#9ab;">A.' + _esc(q.options[0]) + '　B.' + _esc(q.options[1]) + '　C.' + _esc(q.options[2]) + '　D.' + _esc(q.options[3]) + '　✅' + q.answer + '</span></div>';
      }).join('');
      var rms = pendEl.querySelectorAll('._dq-pend-rm');
      for(var r = 0; r < rms.length; r++){
        rms[r].addEventListener('click', function(){
          var pi = parseInt(this.getAttribute('data-pi'), 10);
          if(!isNaN(pi)){ _pending.splice(pi, 1); _renderPending(); }
        });
      }
    }

    // ── 已發佈題目清單(過濾+勾選)──
    function _renderList(){
      if(!_cloudList.length){ listEl.innerHTML = '(目前雲端沒有已發佈的動態題)'; return; }
      var kw = (filterEl && filterEl.value ? filterEl.value : '').trim();
      var shown = 0, html = '';
      for(var i = 0; i < _cloudList.length; i++){
        var q = _cloudList[i];
        if(kw && String(q.question).indexOf(kw) === -1 && String(q.subject).indexOf(kw) === -1) continue;
        if(shown >= 200){ html += '<div style="color:#fa8;">…僅顯示前 200 筆,請用關鍵字縮小範圍。</div>'; break; }
        shown++;
        html += '<div style="border-bottom:1px dashed #445;padding:4px 0;">' +
          '<label style="cursor:pointer;"><input type="checkbox" class="_dq-del-cb" value="' + q.id + '" style="margin-right:6px;">' +
          '<b>#' + q.id + '</b>【' + _esc(q.grade) + '・' + _esc(q.subject) + '・' + _esc(q.difficulty) + '】' + _esc(q.question) +
          ' <span style="color:#9ab;">✅' + _esc(q.answer) + '</span></label></div>';
      }
      listEl.innerHTML = html || '(沒有符合關鍵字的題目)';
    }

    // ── 單題新增 ──
    function _grabForm(){
      function v(id){ var el = document.getElementById(id); return el ? el.value : ''; }
      return {
        grade: v('_admin-dynquiz-grade'), subject: v('_admin-dynquiz-subject'),
        difficulty: v('_admin-dynquiz-diff'), question: v('_admin-dynquiz-question'),
        options: [v('_admin-dynquiz-optA'), v('_admin-dynquiz-optB'), v('_admin-dynquiz-optC'), v('_admin-dynquiz-optD')],
        answer: v('_admin-dynquiz-answer'), hint: v('_admin-dynquiz-hint')
      };
    }
    function _clearForm(){
      var ids = ['_admin-dynquiz-question','_admin-dynquiz-optA','_admin-dynquiz-optB','_admin-dynquiz-optC','_admin-dynquiz-optD','_admin-dynquiz-hint'];
      for(var i = 0; i < ids.length; i++){ var el = document.getElementById(ids[i]); if(el) el.value = ''; }
    }
    addBtn.addEventListener('click', function(){
      var q = _grabForm();
      var err = _validate(q);
      if(err){ _say('⚠ ' + _esc(err), false); return; }
      _pending.push(_norm(q));
      _clearForm(); _renderPending();
      _say('✅ 已加入待發佈清單(共 ' + _pending.length + ' 題)。記得按「🚀 發佈到雲端」才會生效。', true);
    });

    // ── 批次匯入 ──
    parseBtn.addEventListener('click', function(){
      var ta = document.getElementById('_admin-dynquiz-batch');
      var raw = ta ? ta.value.trim() : '';
      if(!raw){ _say('⚠ 批次欄位是空的。', false); return; }
      var arr;
      try{ arr = JSON.parse(raw); }catch(e){ _say('⚠ JSON 解析失敗:' + _esc(e.message), false); return; }
      if(!Array.isArray(arr)){ _say('⚠ 最外層必須是陣列 [ ... ]。', false); return; }
      var okN = 0, errs = [];
      for(var i = 0; i < arr.length; i++){
        var err = _validate(arr[i]);
        if(err){ errs.push('第 ' + (i + 1) + ' 題:' + err); continue; }
        _pending.push(_norm(arr[i])); okN++;
      }
      _renderPending();
      if(errs.length){
        _say('⚠ 成功加入 ' + okN + ' 題;' + errs.length + ' 題有問題未加入:<br>' + _esc(errs.slice(0, 8).join(';')), okN > 0);
      }else{
        if(ta) ta.value = '';
        _say('✅ 批次解析成功,已加入 ' + okN + ' 題到待發佈清單。', true);
      }
    });
    clrBtn.addEventListener('click', function(){ _pending = []; _renderPending(); _say('已清空待發佈清單。', true); });

    // ── 分包寫回(發佈與刪除共用):寫 quiz_N 各包 + 刪多餘舊包 + 更新 _index ──
    async function _writeAll(fullList, nextId){
      var h = _fb(); if(!h) throw new Error('Firestore 未就緒');
      var packs = [];
      var packCount = Math.max(1, Math.ceil(fullList.length / PACK_MAX));
      for(var p = 0; p < packCount; p++){
        var name = 'quiz_' + (p + 1);
        packs.push(name);
        var chunk = fullList.slice(p * PACK_MAX, (p + 1) * PACK_MAX);
        await h.F.setDoc(h.F.doc(h.db, 'dynamicContent', name),
          { list: chunk, count: chunk.length, updatedAt: Date.now() });
      }
      // 刪掉超出的舊包(例:刪題後從 3 包縮成 2 包)
      var oldPacks = (_cloudIdx && Array.isArray(_cloudIdx.quizPacks)) ? _cloudIdx.quizPacks : [];
      for(var o = 0; o < oldPacks.length; o++){
        if(packs.indexOf(oldPacks[o]) === -1){
          try{ await h.F.deleteDoc(h.F.doc(h.db, 'dynamicContent', String(oldPacks[o]))); }catch(_eD){}
        }
      }
      var newVer = Date.now();
      await h.F.setDoc(h.F.doc(h.db, 'dynamicContent', '_index'),
        { quizVer: newVer, quizPacks: packs, quizNextId: nextId, updatedAt: newVer }, { merge: true });
      _cloudIdx.quizVer = newVer; _cloudIdx.quizPacks = packs; _cloudIdx.quizNextId = nextId;
      _cloudList = fullList;
    }

    // ── 發佈 ──
    pubBtn.addEventListener('click', async function(){
      if(!_pending.length){ _say('⚠ 待發佈清單是空的。', false); return; }
      pubBtn.disabled = true; pubBtn.textContent = '🔄 發佈中…';
      try{
        // 發佈前重讀雲端最新(拿最新 nextId 與現有題,避免覆蓋別台 GM 剛發佈的內容)
        var ok = await _loadCloud(true);
        if(!ok) throw new Error('讀取雲端現況失敗,已中止(未寫入任何資料)');
        var nextId = _cloudIdx.quizNextId;
        var toAdd = [];
        for(var i = 0; i < _pending.length; i++){
          var q = _pending[i];
          toAdd.push({ id: nextId, grade: q.grade, subject: q.subject, difficulty: q.difficulty,
            question: q.question, options: q.options, answer: q.answer, hint: q.hint });
          nextId++;
        }
        await _writeAll(_cloudList.concat(toAdd), nextId);
        var n = _pending.length; _pending = [];
        _renderPending(); _renderStatus(); _renderList(); _renderSubjectDatalist();
        // GM 自己這台立即重新同步 → 可以馬上在遊戲裡試玩驗證新題
        try{ if(typeof window._dynContentSync === 'function') window._dynContentSync(true); }catch(_eS){}
        _say('✅ 發佈成功!新增 ' + n + ' 題(雲端共 ' + _cloudList.length + ' 題)。全體玩家下次開機自動生效;你這台已立即生效可直接試玩驗證。', true);
      }catch(e){
        _say('❌ 發佈失敗:' + _esc(e && e.message ? e.message : e), false);
      }
      pubBtn.disabled = false; pubBtn.textContent = '🚀 發佈到雲端(全體玩家下次開機生效)';
    });

    // ── 刪除勾選 ──
    delBtn.addEventListener('click', async function(){
      var cbs = listEl.querySelectorAll('._dq-del-cb');
      var ids = [];
      for(var i = 0; i < cbs.length; i++){ if(cbs[i].checked) ids.push(parseInt(cbs[i].value, 10)); }
      if(!ids.length){ _say('⚠ 沒有勾選任何題目。', false); return; }
      if(!confirm('確定刪除勾選的 ' + ids.length + ' 題?刪除後全體玩家下次開機同步移除。')) return;
      delBtn.disabled = true; delBtn.textContent = '🔄 刪除中…';
      try{
        var ok = await _loadCloud(true);
        if(!ok) throw new Error('讀取雲端現況失敗,已中止(未寫入任何資料)');
        var kept = [];
        for(var k = 0; k < _cloudList.length; k++){
          if(ids.indexOf(_cloudList[k].id) === -1) kept.push(_cloudList[k]);
        }
        await _writeAll(kept, _cloudIdx.quizNextId);   // nextId 不回收,永不重用
        _renderStatus(); _renderList();
        try{ if(typeof window._dynContentSync === 'function') window._dynContentSync(true); }catch(_eS2){}
        _say('✅ 已刪除 ' + ids.length + ' 題(雲端剩 ' + _cloudList.length + ' 題)。', true);
      }catch(e){
        _say('❌ 刪除失敗:' + _esc(e && e.message ? e.message : e), false);
      }
      delBtn.disabled = false; delBtn.textContent = '🗑 刪除勾選的題目(寫回雲端)';
    });

    if(filterEl) filterEl.addEventListener('input', _renderList);
    reloadBtn.addEventListener('click', function(){ _loadCloud(false); });
    setTimeout(function(){ _renderSubjectDatalist(); }, 300);
  })();

  // ════════════════════════════════════════════════════════════════════════════
  // ★ v5.17.0(2026-08-06) — 動態造型配件 init(動態內容層・第二期)
  //   Firestore dynamicContent:_index{avatarVer,avatarPacks,avatarNext} + avatar_N{list}
  //   id=200+分類序號(單調配發永不重用)・永不刪只停用(off:1 佔位制・索引不位移)
  //   套用引擎 window._dynAvatarApply 在 avatar_db.js;定位交由造型工房「📌設為預設」
  // ════════════════════════════════════════════════════════════════════════════
  (function _initDynAvatarSection(){
    var statusEl = document.getElementById('_admin-dynavatar-status');
    var reloadBtn= document.getElementById('_admin-dynavatar-reload');
    var catEl    = document.getElementById('_admin-dynavatar-cat');
    var lockEl   = document.getElementById('_admin-dynavatar-lock');
    var nameEl   = document.getElementById('_admin-dynavatar-name');
    var namesEl  = document.getElementById('_admin-dynavatar-names');
    var fileEl   = document.getElementById('_admin-dynavatar-file');
    var prevEl   = document.getElementById('_admin-dynavatar-preview');
    var addBtn   = document.getElementById('_admin-dynavatar-add');
    var pendEl   = document.getElementById('_admin-dynavatar-pending');
    var pubBtn   = document.getElementById('_admin-dynavatar-publish');
    var clrBtn   = document.getElementById('_admin-dynavatar-clearpending');
    var filterEl = document.getElementById('_admin-dynavatar-filter');
    var saveBtn  = document.getElementById('_admin-dynavatar-save');
    var listEl   = document.getElementById('_admin-dynavatar-list');
    var resEl    = document.getElementById('_admin-dynavatar-result');
    if(!statusEl || !reloadBtn || !pubBtn || !fileEl){
      console.warn('[admin dynavatar] DOM 元素缺失,跳過初始化');
      return;
    }
    var DYN_BASE = 200;            // 動態件最小 id(=陣列索引・與 avatar_db.js _DYN_AV_BASE 一致)
    var PACK_MAX_CHARS = 700000;   // 每包序列化上限(遠低於 Firestore 1MB 文件上限)
    var IMG_MAX_BYTES  = 120000;   // 單件壓縮目標
    var CAT_LABEL  = { hat:'🎩 帽子', gls:'👓 眼鏡', mask:'🎭 面具', mouthacc:'🍭 嘴飾' };
    var LOCK_LABEL = { open:'✅ 直接開放', summon:'🎲 召喚1%', soon:'🔒 暫時上鎖' };

    var _cloudIdx  = null;   // 最近一次讀到的 _index
    var _cloudList = [];     // 最近一次讀到的全部已發佈配件
    var _pending   = [];     // 待發佈(尚無 id)
    var _edits     = {};     // 已發佈項調整暫存 { id: {off:0|1, lock:'open'|'summon'|'soon'} }
    var _curImg    = null;   // 目前壓縮完成的圖 {b64,w,h,bytes,fmt,ar}

    function _esc(t){
      return String(t === undefined || t === null ? '' : t)
        .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }
    function _say(msg, ok){
      if(resEl) resEl.innerHTML = '<span style="color:' + (ok ? '#8fffb0' : '#ff9a9a') + ';">' + msg + '</span>';
    }
    function _fb(){
      var db = window._fbDb, F = window._fbFns;
      if(!db || !F){ _say('❌ Firestore 未就緒,請先在遊戲主頁登入 GM 帳號。', false); return null; }
      return { db: db, F: F };
    }
    function _tsStr(ms){ try{ return new Date(ms).toLocaleString('zh-TW'); }catch(_e){ return String(ms || ''); } }
    function _lockOf(it){
      var e = _edits[it.id];
      if(e && e.lock) return e.lock;
      return (it.lock === 'summon' || it.lock === 'soon') ? it.lock : 'open';
    }
    function _offOf(it){
      var e = _edits[it.id];
      if(e && typeof e.off === 'number') return e.off;
      return it.off ? 1 : 0;
    }
    function _dirtyCount(){ var n = 0, k; for(k in _edits){ n++; } return n; }

    // ── 雲端讀取(現況)──
    function _renderStatus(){
      if(!_cloudIdx || !_cloudIdx.avatarVer){
        statusEl.innerHTML = '尚未發佈過任何動態配件。上傳第一件開始吧!';
        return;
      }
      var cnt = { hat:0, gls:0, mask:0, mouthacc:0 }, off = 0, i, it;
      for(i = 0; i < _cloudList.length; i++){
        it = _cloudList[i];
        if(!it) continue;
        if(cnt[it.cat] !== undefined) cnt[it.cat]++;
        if(it.off) off++;
      }
      statusEl.innerHTML = '☁️ 最後發佈:' + _esc(_tsStr(_cloudIdx.avatarVer))
        + '・共 <b>' + _cloudList.length + '</b> 件(🎩' + cnt.hat + '・👓' + cnt.gls
        + '・🎭' + cnt.mask + '・🍭' + cnt.mouthacc + ')・停用 ' + off + ' 件';
    }
    async function _loadCloud(silent){
      var h = _fb(); if(!h) return false;
      try{
        var snap = await h.F.getDoc(h.F.doc(h.db, 'dynamicContent', '_index'));
        _cloudIdx = snap.exists() ? (snap.data() || {}) : {};
        var packs = Array.isArray(_cloudIdx.avatarPacks) ? _cloudIdx.avatarPacks : [];
        var all = [];
        for(var i = 0; i < packs.length; i++){
          var ps = await h.F.getDoc(h.F.doc(h.db, 'dynamicContent', String(packs[i])));
          if(ps.exists()){ var pd = ps.data(); if(pd && Array.isArray(pd.list)) all = all.concat(pd.list); }
        }
        _cloudList = all;
        _edits = {};
        _renderStatus(); _renderList(); _updSaveBtn();
        if(!silent) _say('✅ 已讀取雲端現況:共 ' + all.length + ' 件。', true);
        return true;
      }catch(e){
        _say('❌ 讀取失敗:' + _esc(e && e.message ? e.message : e) + '(若為 permission 錯誤請確認 firestore.rules 已部署)', false);
        return false;
      }
    }

    // ── 圖片壓縮(WebP 優先・不支援自動退 PNG・逐級縮至 ≦120KB)──
    function _compress(file, cb){
      var fr = new FileReader();
      fr.onload = function(){
        var img = new Image();
        img.onload = function(){
          try{
            var dims = [512, 448, 384, 320, 256], out = null;
            var w0 = img.naturalWidth, h0 = img.naturalHeight;
            if(!w0 || !h0){ cb('圖片尺寸無效'); return; }
            for(var i = 0; i < dims.length; i++){
              var sc = Math.min(1, dims[i] / Math.max(w0, h0));
              var w = Math.max(1, Math.round(w0 * sc)), hh = Math.max(1, Math.round(h0 * sc));
              var cv = document.createElement('canvas');
              cv.width = w; cv.height = hh;
              cv.getContext('2d').drawImage(img, 0, 0, w, hh);
              var d = cv.toDataURL('image/webp', 0.85), fmt = 'webp';
              if(d.indexOf('data:image/webp') !== 0){ d = cv.toDataURL('image/png'); fmt = 'png'; }
              var bytes = Math.round((d.length - d.indexOf(',') - 1) * 3 / 4);
              out = { b64: d, w: w, h: hh, bytes: bytes, fmt: fmt };
              if(bytes <= IMG_MAX_BYTES) break;
            }
            cb(null, out);
          }catch(eC){ cb('壓縮失敗:' + (eC && eC.message ? eC.message : eC)); }
        };
        img.onerror = function(){ cb('圖片讀取失敗(檔案格式不支援)'); };
        img.src = fr.result;
      };
      fr.onerror = function(){ cb('檔案讀取失敗'); };
      fr.readAsDataURL(file);
    }

    // ── 四體型試穿預覽(臨時件 push → render → pop・任何失敗回空字串不影響流程)──
    function _tryOnHtml(cat, ar, b64){
      var PKEY = { hat:'hat', gls:'glasses', mask:'mask', mouthacc:'mouthacc' };
      var PROPK = { hat:'hat', gls:'gls', mask:'mask', mouthacc:'macc' };
      var CFGK = { hat:'hat', gls:'gls', mask:'mask', mouthacc:'macc' };
      try{
        if(typeof window._avatarRenderSVG !== 'function' || !window.AVATAR_PARTS
           || typeof window._avatarDefaultCfg !== 'function') return '';
        var arr = window.AVATAR_PARTS[PKEY[cat]];
        if(!arr) return '';
        var idx = arr.length;
        arr.push({ id: idx, n:'預覽', ns:'預覽', lock:null, img:'dyn_preview', b64: b64,
                   prop: { k: PROPK[cat], ar: ar } });
        var out = '';
        try{
          for(var b = 0; b < 4; b++){
            var cfg = window._avatarDefaultCfg();
            cfg.body = b;
            cfg[CFGK[cat]] = idx;
            out += '<div style="width:110px;">' + window._avatarRenderSVG(cfg, 'width:100%;height:auto;') + '</div>';
          }
        }catch(_eR){ out = ''; }
        arr.pop();   // 一定移除臨時件
        return out;
      }catch(_e){ return ''; }
    }
    function _renderPreview(){
      if(!_curImg){ prevEl.innerHTML = ''; return; }
      var o = _curImg;
      var sizeK = Math.round(o.bytes / 102.4) / 10;
      var warn = (o.bytes > IMG_MAX_BYTES)
        ? ' <span style="color:#ff9a9a;">(⚠ 超過建議 120KB,已盡量壓縮)</span>' : '';
      var tryOn = _tryOnHtml(catEl.value, o.ar, o.b64);
      prevEl.innerHTML = '<div style="display:flex;gap:16px;align-items:flex-start;flex-wrap:wrap;">'
        + '<div><div style="font-size:13px;color:#b0a0d0;">壓縮後 ' + o.w + '×' + o.h + '・' + sizeK + 'KB・' + o.fmt.toUpperCase() + warn + '</div>'
        + '<img src="' + o.b64 + '" style="max-width:150px;max-height:150px;background:repeating-conic-gradient(#333 0 25%,#3f3f3f 0 50%) 0 0/16px 16px;border-radius:8px;margin-top:4px;"/></div>'
        + (tryOn ? ('<div><div style="font-size:13px;color:#b0a0d0;">四體型試穿(定位發佈後在造型工房「📌設為預設」調)</div>'
          + '<div style="display:flex;gap:6px;background:#fff;border-radius:8px;padding:4px;margin-top:4px;">' + tryOn + '</div></div>')
          : '<div style="font-size:13px;color:#9a8ab8;">(試穿預覽需在遊戲主頁載入完成後可用)</div>')
        + '</div>';
    }
    fileEl.addEventListener('change', function(){
      _curImg = null;
      var f = (fileEl.files && fileEl.files[0]) || null;
      if(!f){ prevEl.innerHTML = ''; return; }
      prevEl.innerHTML = '<span style="color:#ffd97a;">⏳ 壓縮中…</span>';
      _compress(f, function(err, out){
        if(err || !out){
          prevEl.innerHTML = '<span style="color:#ff9a9a;">❌ ' + _esc(err || '壓縮失敗') + '</span>';
          return;
        }
        out.ar = out.w / out.h;
        _curImg = out;
        _renderPreview();
      });
    });
    catEl.addEventListener('change', _renderPreview);   // 換分類即重算試穿錨點

    // ── 待發佈 ──
    function _renderPending(){
      if(!_pending.length){ pendEl.innerHTML = '(無)'; return; }
      var htm = '<div style="display:flex;gap:10px;flex-wrap:wrap;">';
      for(var i = 0; i < _pending.length; i++){
        var pnd = _pending[i];
        htm += '<div style="display:flex;gap:8px;align-items:center;padding:7px 10px;background:rgba(70,55,110,0.35);border:1.5px solid rgba(200,160,255,0.4);border-radius:9px;">'
          + '<img src="' + pnd.b64 + '" style="width:40px;height:40px;object-fit:contain;background:#fff;border-radius:6px;">'
          + '<span style="font-size:13.5px;color:#efe4ff;">' + (CAT_LABEL[pnd.cat] || pnd.cat) + '・<b>' + _esc(pnd.n) + '</b>/' + _esc(pnd.ns)
          + '・' + (LOCK_LABEL[pnd.lock] || pnd.lock) + '</span>'
          + '<button data-act="rmpend" data-i="' + i + '" style="padding:4px 9px;font-size:13px;border-radius:7px;cursor:pointer;background:rgba(160,60,60,0.4);border:1.5px solid rgba(230,110,110,0.6);color:#ffdede;">✖</button>'
          + '</div>';
      }
      pendEl.innerHTML = htm + '</div>';
    }
    pendEl.addEventListener('click', function(ev){
      var t = ev.target;
      if(!t || t.getAttribute('data-act') !== 'rmpend') return;
      var i = parseInt(t.getAttribute('data-i'), 10);
      if(i >= 0 && i < _pending.length){ _pending.splice(i, 1); _renderPending(); }
    });
    addBtn.addEventListener('click', function(){
      var n = (nameEl.value || '').trim(), ns = (namesEl.value || '').trim();
      if(!_curImg){ _say('❌ 請先選擇圖片並等壓縮完成。', false); return; }
      if(!n || !ns){ _say('❌ 兩種名稱都必填(精緻風+簡單風・全體玩家會看到)。', false); return; }
      _pending.push({ cat: catEl.value, n: n, ns: ns, lock: lockEl.value,
                      ar: _curImg.ar, b64: _curImg.b64 });
      _renderPending();
      nameEl.value = ''; namesEl.value = ''; fileEl.value = ''; _curImg = null; prevEl.innerHTML = '';
      _say('✅ 已加入待發佈(' + _pending.length + ' 件)。按「🚀 發佈」才會寫入雲端。', true);
    });
    clrBtn.addEventListener('click', function(){
      _pending = []; _renderPending(); _say('已清空待發佈。', true);
    });

    // ── 已發佈清單 ──
    function _updSaveBtn(){
      var n = _dirtyCount();
      saveBtn.disabled = !n;
      saveBtn.textContent = n ? ('💾 儲存變更(' + n + ' 件・寫回雲端)') : '💾 儲存變更(停用/取得方式・寫回雲端)';
    }
    function _renderList(){
      if(!_cloudList.length){ listEl.innerHTML = '(雲端尚無已發佈配件)'; return; }
      var fil = filterEl ? filterEl.value : '';
      var rows = _cloudList.slice().sort(function(a, b){
        var ca = String(a.cat), cb2 = String(b.cat);
        if(ca !== cb2) return ca < cb2 ? -1 : 1;
        return (a.id | 0) - (b.id | 0);
      });
      var htm = '<div style="display:flex;flex-direction:column;gap:7px;">', shown = 0;
      for(var i = 0; i < rows.length; i++){
        var it = rows[i];
        if(!it || typeof it.id !== 'number') continue;
        if(fil && it.cat !== fil) continue;
        shown++;
        var off = _offOf(it), lk = _lockOf(it);
        var chg = _edits[it.id] ? ' box-shadow:0 0 8px rgba(255,220,120,0.55);' : '';
        htm += '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:8px 10px;background:rgba(30,40,66,0.5);border:1.5px solid rgba(130,170,255,0.35);border-radius:9px;' + (off ? 'opacity:0.55;' : '') + chg + '">'
          + (it.b64 ? ('<img src="' + it.b64 + '" style="width:44px;height:44px;object-fit:contain;background:#fff;border-radius:6px;">') : '')
          + '<span style="font-size:13.5px;color:#dce9ff;min-width:210px;">' + (CAT_LABEL[it.cat] || _esc(it.cat))
          + '・#' + it.id + '・<b>' + _esc(it.n) + '</b>/' + _esc(it.ns) + (off ? '・<span style="color:#ffb0b0;">已停用</span>' : '') + '</span>'
          + '<select data-act="lock" data-id="' + it.id + '" style="padding:5px 8px;font-size:13px;border-radius:7px;background:#1c2438;color:#dce9ff;border:1.5px solid rgba(130,170,255,0.45);">'
          + '<option value="open"' + (lk === 'open' ? ' selected' : '') + '>✅ 直接開放</option>'
          + '<option value="summon"' + (lk === 'summon' ? ' selected' : '') + '>🎲 召喚1%</option>'
          + '<option value="soon"' + (lk === 'soon' ? ' selected' : '') + '>🔒 暫時上鎖</option>'
          + '</select>'
          + '<button data-act="off" data-id="' + it.id + '" style="padding:6px 11px;font-size:13px;border-radius:7px;cursor:pointer;'
          + (off ? 'background:rgba(60,110,70,0.4);border:1.5px solid rgba(110,210,140,0.6);color:#d9ffe4;'
                 : 'background:rgba(120,90,40,0.4);border:1.5px solid rgba(230,190,110,0.6);color:#ffedc8;')
          + '">' + (off ? '▶ 重新啟用' : '⏸ 停用') + '</button>'
          + '</div>';
      }
      listEl.innerHTML = shown ? (htm + '</div><div style="font-size:12.5px;color:#8a97b8;margin-top:6px;">停用不會刪除資料,玩家選單隱藏、穿戴中自動變無;之後可隨時重新啟用。調整後記得按「💾 儲存變更」。</div>')
                               : '(此分類尚無配件)';
    }
    function _markEdit(id, patch){
      var it = null, i;
      for(i = 0; i < _cloudList.length; i++){ if(_cloudList[i] && _cloudList[i].id === id){ it = _cloudList[i]; break; } }
      if(!it) return;
      var cur = _edits[id] || { off: (it.off ? 1 : 0), lock: ((it.lock === 'summon' || it.lock === 'soon') ? it.lock : 'open') };
      var k; for(k in patch){ cur[k] = patch[k]; }
      // 若調回原值 → 取消暫存
      var origOff = it.off ? 1 : 0;
      var origLk = (it.lock === 'summon' || it.lock === 'soon') ? it.lock : 'open';
      if(cur.off === origOff && cur.lock === origLk){ delete _edits[id]; }
      else { _edits[id] = cur; }
      _renderList(); _updSaveBtn();
    }
    listEl.addEventListener('click', function(ev){
      var t = ev.target;
      if(!t || t.getAttribute('data-act') !== 'off') return;
      var id = parseInt(t.getAttribute('data-id'), 10);
      var it = null, i;
      for(i = 0; i < _cloudList.length; i++){ if(_cloudList[i] && _cloudList[i].id === id){ it = _cloudList[i]; break; } }
      if(!it) return;
      _markEdit(id, { off: _offOf(it) ? 0 : 1 });
    });
    listEl.addEventListener('change', function(ev){
      var t = ev.target;
      if(!t || t.getAttribute('data-act') !== 'lock') return;
      var id = parseInt(t.getAttribute('data-id'), 10);
      _markEdit(id, { lock: t.value });
    });
    if(filterEl) filterEl.addEventListener('change', _renderList);

    // ── 寫入(發佈/儲存變更共用):先重讀雲端最新 → 合併 → 分包寫回 ──
    async function _writeAll(h, items, next, oldIdx){
      var packsArr = [], cur = [], curLen = 2, i;
      for(i = 0; i < items.length; i++){
        var sJ = JSON.stringify(items[i]);
        if(cur.length && (curLen + sJ.length + 1) > PACK_MAX_CHARS){ packsArr.push(cur); cur = []; curLen = 2; }
        cur.push(items[i]); curLen += sJ.length + 1;
      }
      if(cur.length || !packsArr.length) packsArr.push(cur);
      var names = [];
      for(i = 0; i < packsArr.length; i++){
        var nm = 'avatar_' + (i + 1);
        names.push(nm);
        await h.F.setDoc(h.F.doc(h.db, 'dynamicContent', nm),
          { list: packsArr[i], count: packsArr[i].length, updatedAt: Date.now() });
      }
      var oldPacks = Array.isArray(oldIdx.avatarPacks) ? oldIdx.avatarPacks : [];
      for(i = 0; i < oldPacks.length; i++){
        if(names.indexOf(String(oldPacks[i])) === -1){
          try{ await h.F.deleteDoc(h.F.doc(h.db, 'dynamicContent', String(oldPacks[i]))); }catch(_eD){}
        }
      }
      await h.F.setDoc(h.F.doc(h.db, 'dynamicContent', '_index'),
        { avatarVer: Date.now(), avatarPacks: names, avatarNext: next, updatedAt: Date.now() },
        { merge: true });
    }
    async function _readFresh(h){
      var snap = await h.F.getDoc(h.F.doc(h.db, 'dynamicContent', '_index'));
      var idx = snap.exists() ? (snap.data() || {}) : {};
      var packs = Array.isArray(idx.avatarPacks) ? idx.avatarPacks : [];
      var all = [];
      for(var i = 0; i < packs.length; i++){
        var ps = await h.F.getDoc(h.F.doc(h.db, 'dynamicContent', String(packs[i])));
        if(ps.exists()){ var pd = ps.data(); if(pd && Array.isArray(pd.list)) all = all.concat(pd.list); }
      }
      return { idx: idx, list: all };
    }
    pubBtn.addEventListener('click', async function(){
      if(!_pending.length){ _say('❌ 沒有待發佈的配件。', false); return; }
      var h = _fb(); if(!h) return;
      pubBtn.disabled = true; pubBtn.textContent = '⏳ 發佈中…';
      try{
        var fresh = await _readFresh(h);   // 防多 GM 互蓋:以雲端最新為底
        var next = fresh.idx.avatarNext || {};
        var items = fresh.list.slice();
        for(var i = 0; i < _pending.length; i++){
          var pnd = _pending[i];
          var nid = DYN_BASE + ((next[pnd.cat] | 0));
          next[pnd.cat] = (next[pnd.cat] | 0) + 1;
          items.push({ id: nid, cat: pnd.cat, n: pnd.n, ns: pnd.ns,
                       lock: (pnd.lock === 'open' ? '' : pnd.lock), ar: pnd.ar, b64: pnd.b64, off: 0 });
        }
        await _writeAll(h, items, next, fresh.idx);
        var cnt = _pending.length;
        _pending = []; _renderPending();
        try{ if(typeof window._dynContentSync === 'function') window._dynContentSync(true); }catch(_eS){}
        await _loadCloud(true);
        _say('🚀 發佈完成:新增 ' + cnt + ' 件!GM 本機已即時生效,可到造型工房試穿並「📌設為預設」調定位;全體玩家下次開機生效。', true);
      }catch(e){
        _say('❌ 發佈失敗:' + _esc(e && e.message ? e.message : e), false);
      }
      pubBtn.disabled = false; pubBtn.textContent = '🚀 發佈(寫入雲端・全體玩家生效)';
    });
    saveBtn.addEventListener('click', async function(){
      if(!_dirtyCount()){ return; }
      var h = _fb(); if(!h) return;
      saveBtn.disabled = true; saveBtn.textContent = '⏳ 寫回中…';
      try{
        var fresh = await _readFresh(h);   // 同樣先重讀最新
        var items = fresh.list.slice();
        var n = 0;
        for(var i = 0; i < items.length; i++){
          var it = items[i];
          if(!it || !_edits[it.id]) continue;
          var e = _edits[it.id];
          it.off = e.off ? 1 : 0;
          it.lock = (e.lock === 'open') ? '' : e.lock;
          n++;
        }
        await _writeAll(h, items, fresh.idx.avatarNext || {}, fresh.idx);
        try{ if(typeof window._dynContentSync === 'function') window._dynContentSync(true); }catch(_eS2){}
        await _loadCloud(true);
        _say('💾 已寫回 ' + n + ' 件變更,全體玩家下次開機生效。', true);
      }catch(e){
        _say('❌ 寫回失敗:' + _esc(e && e.message ? e.message : e), false);
      }
      _updSaveBtn(); saveBtn.textContent = '💾 儲存變更(停用/取得方式・寫回雲端)';
    });

    reloadBtn.addEventListener('click', function(){ _loadCloud(false); });
  })();

