      var _items = (_batches || []).map(function(b){
        return '<span style="display:inline-block;margin:2px 4px;padding:3px 10px;background:rgba(120,180,255,0.16);border:1px solid rgba(120,180,255,0.5);border-radius:10px;color:#bcd8ff;font-weight:700;">🎁 ' + _esc(b.date) + ' <span style="color:#8ab0e0;">' + (b.count||0) + ' 隻</span></span>';
      }).join('');
      var _nr = _noRecordTotal ? ('<span style="display:inline-block;margin:2px 4px;padding:3px 10px;background:rgba(200,200,200,0.14);border:1px solid rgba(200,200,200,0.4);border-radius:10px;color:#ccc;font-weight:700;">❓ 查無日期 ' + _noRecordTotal + ' 隻</span>') : '';
      return '<div style="margin-bottom:12px;padding:10px 12px;background:rgba(30,40,55,0.6);border:1px solid rgba(120,180,255,0.4);border-radius:7px;">'
